content:
:root { --dur-fast: .18s; --dur: .3s; --dur-slow: .4s; --accent: #2b6cb0; --accent-dark: #1f4e86; --accent-soft: #eaf2fb; --accent-line: #c9dcf0;
  --btn: #2b6cb0; --btn-dark: #1f4e86;
  --brand: #7030A0; --brand-dark: #55267a; --brand-soft: #f5eefa; --brand-line: #dcc8ec; --new: var(--brand); --warn: #8a5a00; --warn-bg: #fff4d6; --warn-line: #f0d58a; --danger: #c0392b;
  --danger-text: #b02a37; --danger-bg: #fff7f6; --amber-text: #b45309;
  --text: #1f2933; --muted: #4b535a; --faint: #6b737a; --line: #dfe4ea; --line-strong: #ccd3da;
  --page: #f5f7fa; --page-rgb: 245,247,250; --surface: #ffffff; --surface-2: #f5f7fa; --surface-3: #eceff2; --hover: #f0f4f8;
  --shimmer-a: #eef1f5; --shimmer-b: #f8fafc; }
/* Dark theme: the same variables, set when the page carries data-theme="dark" (see the toggle in the header) */
html[data-theme="dark"] { color-scheme: dark;
  --accent: #5ba0e6; --accent-dark: #8dbcf0; --accent-soft: #1b2b3d; --accent-line: #2a4561;
  --btn: #2b6cb0; --btn-dark: #3a7bc4;
  --brand: #b78bdf; --brand-dark: #d2b4ee; --brand-soft: #251a30; --brand-line: #44325a; --new: var(--brand); --warn: #e6b15c; --warn-bg: #2f2612; --warn-line: #5c4a1f; --danger: #e5604f;
  --danger-text: #f08a7d; --danger-bg: #2a1715; --amber-text: #f0a35a;
  --text: #e4e8ec; --muted: #a4afba; --faint: #8a95a1; --line: #2b343e; --line-strong: #3a4551;
  --page: #0f1419; --page-rgb: 15,20,25; --surface: #171d24; --surface-2: #1d252e; --surface-3: #26303b; --hover: #222c37;
  --shimmer-a: #1d252e; --shimmer-b: #26303b; }
body { background: var(--page); color: var(--text); font-size: 14.5px; }
h4 { font-weight: 600; }
h1, h2, h3, h4 { letter-spacing: -0.01em; }
.well { background: var(--surface); border: 1px solid var(--line); box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
.btn-primary { background: var(--btn); border-color: var(--btn-dark); }
.btn-primary:hover, .btn-primary:focus, .btn-primary:active, .btn-primary.active { background: var(--btn-dark); border-color: var(--btn-dark); }
.nav-tabs > li.active > a, .nav-tabs > li.active > a:hover, .nav-tabs > li.active > a:focus { color: var(--accent-dark); background: var(--page); border-color: var(--line) var(--line) var(--page); font-weight: 600; }
.nav-tabs > li > a { color: var(--muted); }
.nav-tabs > li > a:hover { background: var(--accent-soft); border-color: var(--line); }
a { color: var(--accent); } a:hover { color: var(--accent-dark); }
.selectize-input.focus, .form-control:focus { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-line); }
/* Results tabs look muted until there is something to read in them */
body:not(.has-results) #tabs > li > a[data-value='Forecast'],
body:not(.has-results) #tabs > li > a[data-value='Sensitivity'],
body:not(.has-results) #tabs > li > a[data-value='Assumption draws'],
body:not(.has-results) #tabs > li > a[data-value='Survival curves'] { color: var(--faint); }
.empty-state { text-align: center; padding: 34px 20px; margin: 10px 0 14px; border: 1px dashed var(--line-strong);
  border-radius: 8px; background: var(--surface); }
.empty-title { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.empty-text { color: var(--muted); margin: 0 auto 14px; max-width: 460px; }
body.has-results .empty-state { display: none; }
body:not(.has-results) .results-body { display: none; }
.run-dock { position: relative; z-index: 5; background: var(--surface); margin-top: 10px; padding: 10px 14px 12px; flex: none;
  border: 1px solid var(--line); border-radius: 4px; box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
#run { font-weight: 600; letter-spacing: 0.01em; box-shadow: 0 1px 2px rgba(16,24,40,0.2); }
.sec-count { margin-left: 8px; font-size: 12px; font-weight: 400; color: var(--muted); }
.sec-desc { font-size: 12.5px; color: var(--muted); margin: -4px 0 8px; }
.card-legend { font-size: 12px; color: var(--muted); display: grid; grid-template-rows: 0fr; opacity: 0;
  transition: grid-template-rows var(--dur) ease, opacity var(--dur) ease; }
.card-legend-in { overflow: hidden; min-height: 0; display: flex; flex-wrap: wrap; gap: 4px 14px; padding-bottom: 0;
  transition: padding-bottom var(--dur) ease; }
.card-legend.on .card-legend-in { padding-bottom: 10px; }
.card-legend span::before { content: ''; display: inline-block; width: 3px; height: 11px; margin-right: 5px;
  vertical-align: -1px; border-radius: 2px; background: #c3cad1; }
.card-legend .lg-edit::before { background: var(--btn); }
.card-legend .lg-run::before { background: #e0a800; }
.card-legend .lg-up::before { background: var(--new); }
.assump-card { transition: box-shadow var(--dur-fast) ease, border-color var(--dur-fast) ease, background-color var(--dur-fast) ease; }
.assump-card:not(.card-off):hover { box-shadow: 0 3px 10px rgba(16,24,40,0.14); border-color: var(--accent); }

@media (max-width: 767px) { html { overflow-y: scroll; } }
.container-fluid { padding-top: 14px; }
.container-fluid > h2 { margin: 8px 0 28px; }
.app-brand { display: flex; align-items: center; gap: 14px; }
.app-logo { height: 38px; width: auto; display: block; }
.app-mosquito { height: 36px; width: auto; display: block; margin-left: -14px; }
.app-brand-text { font-size: 22px; font-weight: 400; color: var(--muted); line-height: 1.2; }
@media (max-width: 500px) { .app-brand-text { font-size: 16px; } .app-logo { height: 30px; } .app-mosquito { height: 28px; } }
body { padding-bottom: 36px; }
.app-footer { position: fixed; left: 0; bottom: 0; z-index: 1000; padding: 4px 14px;
  font-size: 12px; color: var(--muted); background: rgba(var(--page-rgb), 0.92);
  border-top-right-radius: 6px; }
.well { padding: 12px 14px; }
.well a:not(.btn) { color: var(--accent-dark); }
.well .form-group { margin-bottom: 8px; }
.well label.control-label { margin-bottom: 2px; font-size: 13px; }
.well .form-control { height: 30px; padding: 3px 8px; font-size: 13px; }
.well .selectize-input { min-height: 30px; padding: 4px 8px; }
#n_iter + .selectize-control.single .selectize-input { padding-right: 22px; font-size: 12px; white-space: nowrap; }
.well .row > [class*='col-'] { padding-left: 5px; padding-right: 5px; }
.well .row { margin-left: -5px; margin-right: -5px; }
#shiny-notification-panel { position: static; width: 100%; margin-top: 10px; }
#shiny-notification-panel .shiny-notification { position: relative; width: 100%;
  margin: 0 0 8px; right: auto; z-index: 1100; }
#tabs > li > a[data-value='Forecast']::before,
#tabs > li > a[data-value='Sensitivity']::before,
#tabs > li > a[data-value='Assumption draws']::before,
#tabs > li > a[data-value='Survival curves']::before {
  content: ''; display: inline-block; box-sizing: border-box; width: 7px; height: 7px;
  margin: 0 8.5px 0 1.5px; border-radius: 50%; border: 1.5px solid var(--line-strong); background: transparent;
  vertical-align: middle; position: relative; top: -1px;
  transition: background-color var(--dur), border-color var(--dur), box-shadow var(--dur); }
/* Three pulses, each a ring that expands and fades while the steady glow stays put, so after
   the third pulse the dot simply stays lit with no jump. */
#tabs > li > a.tab-new::before { background: var(--new); border-color: var(--new);
  box-shadow: 0 0 0 0 rgba(111,66,193,0), 0 0 6px 2px rgba(111,66,193,0.5);
  animation: dot-pulse 1.2s ease-out 3; }
@keyframes dot-pulse {
  0%   { box-shadow: 0 0 0 0 rgba(111,66,193,0.6), 0 0 6px 2px rgba(111,66,193,0.5); }
  75%  { box-shadow: 0 0 0 10px rgba(111,66,193,0), 0 0 6px 2px rgba(111,66,193,0.5); }
  100% { box-shadow: 0 0 0 10px rgba(111,66,193,0), 0 0 6px 2px rgba(111,66,193,0.5); } }
.assump-desc { font-size: 12px; line-height: 1.3; color: var(--muted); margin: 2px 0 8px; }
.tab-content > .tab-pane.fade { transition: opacity var(--dur-fast) ease; }
@keyframes fade-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.recalculating { opacity: 0.55 !important; }
.shiny-image-output, .shiny-html-output, .shiny-bound-output img { transition: opacity var(--dur-slow) ease; }
.stale-note { animation: none; }   /* its height and fade are animated in pvec.js (growStaleNote) */
@keyframes slide-in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
#preset .radio label span, .btn { transition: background-color var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast); }
#run.running { cursor: progress; animation: none;
  background: linear-gradient(90deg, var(--btn-dark) var(--p, 0%), var(--btn) var(--p, 0%)); }
#run.running:disabled { opacity: 1; }
.shiny-progress-notification.run-progress { display: none; }
@keyframes run-pulse { 0%, 100% { opacity: 0.95; } 50% { opacity: 0.6; } }
#run {  position: relative; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; } }
.stale-note { font-size: 12px; color: var(--warn); background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 4px; padding: 5px 8px; margin-top: 8px; }
.preset-reset { font-size: 12px; margin: 0 0 8px; }
.assump-invalid { border-color: #dc3545 !important; box-shadow: 0 0 0 1px #dc3545; }
.assump-err { color: var(--danger-text); font-size: 12px; margin-top: 4px; }
.assump-err:empty { display: none; }
.check-result { font-size: 13px; color: var(--muted); margin-top: 8px; }
input:-moz-ui-invalid { box-shadow: none; }
input:disabled, .form-control:disabled { background: var(--surface-2); color: var(--faint); cursor: not-allowed; }
/* Fixed frame on larger screens: title, settings and tab bar stay put; only tab content scrolls */
@media (min-width: 768px) {
  html, body { height: 100%; overflow: hidden; }
  body { padding-bottom: 0; }
  .container-fluid { height: 100vh; display: flex; flex-direction: column; padding-bottom: 34px; }
  .container-fluid > h2 { flex: none; margin: 6px 0 18px; }
  .container-fluid > .row { flex: 1 1 auto; min-height: 0; display: flex; }
  .container-fluid > .row::before, .container-fluid > .row::after { content: none; }
  .container-fluid > .row > .col-sm-3 { display: flex; flex-direction: column; max-height: 100%; padding-bottom: 8px; }
  .container-fluid > .row > .col-sm-3 > .well { flex: 0 1 auto; min-height: 0; overflow-y: auto; margin-bottom: 0; }
  .container-fluid > .row > .col-sm-9 { display: flex; flex-direction: column; min-height: 0; }
  .container-fluid > .row > .col-sm-9 > .tabbable { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
  .tabbable > .nav-tabs { flex: none; }
  .tabbable > .tab-content { flex: 1 1 auto; min-height: 0; overflow-y: scroll; overflow-x: hidden;
    padding: 0 6px 0 0; }
  /* Spacer at rest; once you scroll it sticks under the tabs and blurs what slides beneath */
  .tabbable > .tab-content::before { content: ''; display: block; position: sticky; top: 0; z-index: 20;
    height: 22px; pointer-events: none;
    background: linear-gradient(to bottom, rgba(var(--page-rgb), 0.92), rgba(var(--page-rgb), 0));
    -webkit-backdrop-filter: blur(7px); backdrop-filter: blur(7px);
    -webkit-mask-image: linear-gradient(to bottom, #000 55%, transparent);
    mask-image: linear-gradient(to bottom, #000 55%, transparent); }
  /* Pull the jump bar up over the spacer so its top gap matches the gap under the chips */
  .jump-bar { margin-top: -22px; }
  /* Slide-out settings panel: the column keeps its width and slides off to the left */
  .container-fluid > .row > .col-sm-3 { transition: margin-left var(--dur-slow) ease, opacity var(--dur) ease, visibility 0s linear 0s; }
  .container-fluid > .row > .col-sm-9 { transition: width var(--dur-slow) ease, margin-left var(--dur-slow) ease; }
  .sidebar-collapsed > .row > .col-sm-3 { margin-left: -25%; opacity: 0; visibility: hidden;
    pointer-events: none; transition: margin-left var(--dur-slow) ease, opacity var(--dur) ease, visibility 0s linear var(--dur-slow); }
  .sidebar-collapsed > .row > .col-sm-9 { width: calc(100% - 30px); margin-left: 30px; }
  .sidebar-collapsed .sidebar-arrow-open { opacity: 1; visibility: visible; transition: opacity var(--dur) ease var(--dur), visibility 0s; }
}
.howto { position: relative;
   font-size: 13px; margin-bottom: 14px; }
.howto-steps {  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));  }
.howto-step { display: flex; gap: 10px; align-items: flex-start;
     }
.howto-num { flex: none; width: 24px; height: 24px; border-radius: 50%;  color: #fff;
  font-weight: 700; font-size: 13px; line-height: 24px; text-align: center; }
.howto-step-title { font-weight: 700; font-size: 13px; margin-bottom: 1px; }
.howto-step-text { font-size: 12.5px; line-height: 1.4; color: var(--text); }
.howto-step-text kbd { font-size: 11px; padding: 0 5px; color: var(--text); background: var(--surface-2);
  border: 1px solid var(--line-strong); border-radius: 3px; box-shadow: none; white-space: nowrap; }
.howto-note {  font-size: 12px;  display: flex; align-items: center; gap: 7px; }
.legend-dot { flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--new);
  box-shadow: 0 0 5px 1px rgba(111,66,193,0.5); }
.tab-content { padding-top: 16px; }
@media (min-width: 768px) { .tab-content { padding-top: 0; } }
#rand_seed { font-size: 14px; margin-left: 5px; text-decoration: none; }
.settings-io { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-start; justify-content: flex-start; margin: 0 0 10px; }
.settings-io .form-group { margin: 0; height: 30px; width: auto; }
.settings-io .input-group { display: block; }
.settings-io .input-group .form-control { display: none; }
.settings-io .input-group-btn { display: block; width: auto; }
.settings-io .btn-file, .settings-io .btn { border-radius: 3px; font-size: 12px; padding: 0 12px; height: 30px;
  line-height: 28px; margin: 0; display: inline-block; box-sizing: border-box; }
.settings-io .progress { display: none; }
.dist-help { font-size: 12px; line-height: 1.3; color: var(--muted); margin: -2px 0 8px; }
.assump-card.card-off { position: relative; }
.assump-card.card-off > * { opacity: 0.5; filter: grayscale(1); }
.assump-card.card-off::after { content: ''; position: absolute; top: 0; right: 0; bottom: 0; left: 0;
  cursor: not-allowed; z-index: 5; }
.assump-card.card-off::before { content: attr(data-tip); position: absolute; left: 50%; top: 50%; z-index: 10;
  transform: translate(-50%, -50%); width: 86%; padding: 6px 10px; border-radius: 4px; text-align: center;
  font-size: 12px; line-height: 1.3; color: #fff; background: rgba(33, 37, 41, 0.92); pointer-events: none;
  opacity: 0; transition: opacity var(--dur-fast) ease; }
.assump-card.card-off:hover::before { opacity: 1; }
@media (prefers-reduced-motion: reduce) { .assump-card.card-off::before { transition: none; } }
.fit-help { margin: 4px 0 8px; font-size: 12px; }
.fit-help summary { cursor: pointer; color: var(--accent-dark); margin-bottom: 4px; }
.fit-help .fit-note, .fit-msg { font-size: 12px; line-height: 1.3; color: var(--muted); margin-bottom: 6px; }
.fit-msg.bad { color: var(--danger-text); }
.assump-note { font-size: 12px; line-height: 1.3; color: var(--warn); background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 4px; padding: 4px 6px; margin: 0 0 8px; }
.link-box { background: var(--surface-2); border: 1px solid var(--line); border-radius: 6px; padding: 10px 14px 12px; margin-bottom: 14px; }
.corr-add { margin-top: 25px; }
.corr-row { font-size: 13px; padding: 3px 0; border-bottom: 1px solid var(--line); }
.corr-row a { margin-left: 10px; font-size: 12px; }
.corr-row.inactive { color: var(--muted); }
.assump-upload { color: var(--accent-dark); font-size: 12px; margin-top: 4px; }
.assump-upload:empty { display: none; }
.assump-card.assump-uploaded { border-left: 3px solid var(--new); }
.assump-card.assump-differs { border-left: 3px solid var(--accent); }
.jump-bar { position: sticky; top: 0; z-index: 25;  display: flex; flex-wrap: wrap;
  align-items: center; gap: 6px; padding: 8px 0; margin-bottom: 10px; border-bottom: 1px solid var(--line); }
.jump-chip { border: 1px solid var(--line-strong); background: var(--surface); color: var(--text); border-radius: 14px; padding: 2px 11px;
  font-size: 12.5px; cursor: pointer; transition: background-color var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast); }
.jump-chip:hover { background: var(--hover); }
.jump-chip { position: relative; }
.jump-chip[data-tip]::after { content: attr(data-tip); position: absolute; left: 0; top: calc(100% + 8px); z-index: 40;
  width: 250px; padding: 6px 10px; border-radius: 4px; text-align: left; white-space: normal;
  font-size: 12px; line-height: 1.35; color: #fff; background: rgba(33, 37, 41, 0.94); pointer-events: none;
  opacity: 0; visibility: hidden; transition: opacity var(--dur-fast) ease var(--dur), visibility 0s linear var(--dur-slow); }
.jump-chip[data-tip]:hover::after, .jump-chip[data-tip]:focus-visible::after { opacity: 1; visibility: visible;
  transition: opacity var(--dur-fast) ease var(--dur), visibility 0s linear var(--dur); }
@media (prefers-reduced-motion: reduce) { .jump-chip[data-tip]::after { transition: none; } }
.jump-chip.active { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
.jump-count { margin-left: 6px; font-size: 11px; opacity: 0.85; }
.jump-count:empty { display: none; }
.jump-actions { margin-left: auto; font-size: 12px; color: var(--muted); }
.jump-sep { margin: 0 6px; color: var(--faint); }
.link-btn { border: 0; background: none; padding: 0; color: var(--accent-dark); cursor: pointer; font-size: inherit; }
.link-btn:hover { text-decoration: underline; }
.howto-open { display: none; font-size: 12.5px; margin: 0 0 8px; }
.assump-section { scroll-margin-top: 54px; margin-bottom: 16px; }
.cards-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 215px)); gap: 12px; align-items: start; justify-content: start; }
.assump-card { margin: 0; cursor: pointer; }
.assump-body { cursor: default; }
.assump-toggle { display: flex; gap: 6px; align-items: flex-start; flex: 1; border: 0; background: none; padding: 0;
  text-align: left; cursor: pointer; font-size: 14px; color: inherit; }
.chev { flex: none; font-size: 10px; margin-top: 5px; color: var(--muted); transition: transform var(--dur) ease; }
.assump-card.open .chev, .adv-open .chev { transform: rotate(90deg); }
.assump-summary { font-size: 12px; color: var(--muted);  line-height: 1.3; }
/* Open and close: the row height animates between 0 and its natural height, the content fades,
   and a closed body is hidden from the keyboard and screen readers once it has finished closing */
.assump-body, .adv-body { display: grid; grid-template-rows: 0fr; visibility: hidden;
  transition: grid-template-rows var(--dur-slow) cubic-bezier(.4,0,.2,1), visibility 0s linear var(--dur-slow); }
.assump-card.open .assump-body, .adv-open .adv-body { grid-template-rows: 1fr; visibility: visible;
  transition: grid-template-rows var(--dur-slow) cubic-bezier(.4,0,.2,1), visibility 0s; }
.assump-body-clip, .adv-clip { overflow: hidden; min-height: 0; }
.assump-body-pad { margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--line); opacity: 0;
  transition: opacity var(--dur-fast) ease; }
.assump-card.open .assump-body-pad { opacity: 1; transition: opacity var(--dur) ease var(--dur-fast); }
.adv-clip > .link-box { margin-top: 8px; opacity: 0; transition: opacity var(--dur-fast) ease; }
.adv-open .adv-clip > .link-box { opacity: 1; transition: opacity var(--dur) ease var(--dur-fast); }
.fold { margin: 6px 0 14px; }
.fold .adv-toggle strong { font-size: 18px; font-weight: 500; }
.adv-clip > .eq-pad { margin-top: 8px; opacity: 0; transition: opacity var(--dur-fast) ease; }
.adv-open .adv-clip > .eq-pad { opacity: 1; transition: opacity var(--dur) ease var(--dur-fast); }
.adv-toggle { display: flex; gap: 6px; align-items: center; border: 0; background: none; padding: 4px 0;
  cursor: pointer; font-size: 16px; text-align: left; }
.adv-tag { font-size: 11px; color: var(--muted); border: 1px solid var(--line-strong); border-radius: 9px; padding: 0 7px; }
.adv-status { font-size: 12.5px; color: var(--muted); margin-left: 4px; }
.draws-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 10px; }
.draw-tile { cursor: zoom-in; border: 1px solid var(--line);   background: var(--surface);
   }
.draw-tile:hover, .draw-tile:focus-visible {  border-color: var(--accent); }
.assump-warn { color: var(--warn); font-size: 12px; margin-top: 4px; }
.assump-warn:empty { display: none; }
a:focus-visible, button:focus-visible, .btn:focus-visible, input:focus-visible,
select:focus-visible, .selectize-input.focus, .nav-tabs > li > a:focus-visible {
  outline: 2px solid var(--accent); outline-offset: 2px; }
.btn-file:focus-within { outline: 2px solid var(--accent); outline-offset: 2px; }
.assump-prev { margin-top: 4px; }
.container-fluid { position: relative; }
.settings-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.well { position: relative; }
.sidebar-arrow, .sidebar-arrow-open { border: 1px solid var(--line-strong); background: var(--surface); color: var(--muted); border-radius: 50%;
  width: 24px; height: 24px; padding: 0; font-size: 11px; line-height: 22px; text-align: center; cursor: pointer;
  transition: background-color var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast); }
.sidebar-arrow:hover, .sidebar-arrow-open:hover { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
.sidebar-arrow-open { position: absolute; left: 15px; top: 76px; z-index: 30; opacity: 0; visibility: hidden;
  transition: opacity var(--dur-fast) ease, visibility 0s linear var(--dur-fast); }
@media (max-width: 767px) { .sidebar-arrow, .sidebar-arrow-open { display: none; } }
.assump-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 6px; }
.edited-tools { display: none; flex-direction: column; align-items: flex-end; font-size: 11px; line-height: 1.3; }
.edited-badge { display: none; background: var(--warn-bg); color: var(--warn); border: 1px solid var(--warn-line); border-radius: 9px;
  padding: 0 7px; white-space: nowrap; }
.edited-tools a { display: none; }
.assump-changed .edited-tools, .assump-differs .edited-tools { display: flex; }
.assump-changed .edited-badge { display: inline-block; }
.assump-differs .edited-tools a { display: inline; }
.assump-card.assump-changed { border-left: 3px solid #e0a800; }
.fade-btn { position: relative; }
.fade-btn .fb-a { display: inline-block; transition: opacity var(--dur) ease var(--dur-fast); }
.fade-btn .fb-b { position: absolute; top: 0; right: 0; bottom: 0; left: 0; display: flex;
  align-items: center; justify-content: center; white-space: nowrap; opacity: 0;
  transition: opacity var(--dur-fast) ease; pointer-events: none; }
/* Going in: old text fades out, then the confirmation fades in. Coming back: the reverse. */
.fade-btn .fb-icon { margin-right: 6px; }
.fade-btn.copied .fb-a { opacity: 0; transition: opacity var(--dur-fast) ease; }
.fade-btn.copied .fb-b { opacity: 1; transition: opacity var(--dur) ease var(--dur-fast); }
.compare-table table { font-size: 13px; margin: 4px 0 4px; }
.compare-table td, .compare-table th { padding: 3px 10px; border: 1px solid var(--line); }
.compare-table th { background: var(--surface-2); }
.table-tools { margin: 6px 0 4px; }
.print-only { display: none; }
@media print {
  html, body { height: auto !important; overflow: visible !important; }
  .container-fluid { height: auto !important; display: block !important; padding: 0 !important; }
  .container-fluid > h2 { margin: 0 0 8px !important; }
  .container-fluid > .row { display: block !important; }
  .container-fluid > .row > .col-sm-3, .nav-tabs, .app-footer, .sidebar-arrow, .sidebar-arrow-open, .dl-row, .howto,
  .settings-io, .no-print, .edited-tools, .jump-bar, .howto-open, .chev, .table-tools, .tab-content::before { display: none !important; }
  .container-fluid > .row > .col-sm-9 { width: 100% !important; float: none !important; display: block !important; }
  .tabbable { display: block !important; }
  .tab-content { overflow: visible !important; height: auto !important; padding: 0 !important; }
  .well { break-inside: avoid; }
  .assump-body, .adv-body { grid-template-rows: 1fr !important; visibility: visible !important; }
  .assump-body-pad, .adv-clip > .link-box, .adv-clip > .eq-pad { opacity: 1 !important; }
  img { max-width: 100% !important; }
  .print-only { display: block; font-size: 12px; color: var(--muted); margin: 0 0 10px; }
}
.dl-row { margin: 4px 0 10px; }
.dl-row .btn { margin-right: 6px; }
.forecast-summary { font-size: 15px; margin: 6px 0 4px; }
.forecast-note { font-size: 12px; color: var(--muted); margin: 0 0 8px; }
.cert-text { margin-top: 25px; }
.eq { font-family: 'Times New Roman', Times, serif; font-size: 17px; background: var(--surface-2); border-left: 3px solid var(--accent);
  padding: 8px 14px; margin: 8px 0 12px; overflow-x: auto; white-space: nowrap; }
.eq .fr { display: inline-block; vertical-align: middle; text-align: center; margin: 0 3px; }
.eq .fr > span { display: block; padding: 0 4px; line-height: 1.25; }
.eq .fr > span + span { border-top: 1px solid var(--text); }
.eq .sm { display: inline-block; vertical-align: middle; text-align: center; margin: 0 3px; line-height: 1.05; }
.eq .sm > span { display: block; font-size: 11px; }
.eq-note { font-size: 13px; color: var(--muted); margin: -4px 0 12px; }
.app-meta { font-size: 12px; color: var(--muted); }
.run-status { font-size: 12px; color: var(--muted); margin-top: 6px; }
.start-over { font-size: 12px; margin-top: 10px; }
#preset > label.control-label { display: block; margin-bottom: 4px; }
#preset .shiny-options-group { margin-top: 0; }
#preset .radio label { display: block; padding: 0; width: 100%; }
#preset input[type=radio] { position: absolute; opacity: 0; pointer-events: none; }
#preset .radio label span { display: block;  font-size: 13px; border: 1px solid var(--line-strong);
   background: var(--surface); color: var(--text); cursor: pointer; }
#preset .radio label:hover span { background: var(--hover); }
#preset .radio label:hover input:checked + span { background: var(--btn-dark); }
#preset input:checked + span { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
#preset input:checked + span::before {  font-weight: bold; }
#preset input:focus-visible + span { outline: 2px solid #66afe9; outline-offset: 1px; }
.preset-desc { font-size: 12px; line-height: 1.3; color: var(--muted); margin: 0 0 8px; }
.author-card { display: flex; align-items: center; gap: 24px; max-width: 640px;
  padding: 20px 24px; background: var(--surface-2); border: 1px solid var(--line);
  border-radius: 12px; box-shadow: 0 2px 6px rgba(0,0,0,0.06); }
.author-photo { width: 130px; height: 130px; flex: none; border-radius: 50%;
  object-fit: cover; border: 3px solid var(--surface); box-shadow: 0 1px 4px rgba(0,0,0,0.25); }
.author-label { font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--muted); margin-bottom: 2px; }
.author-text h4 { margin: 0 0 6px; }
.author-text p { margin: 0 0 6px; }
.author-link { font-size: 14px; margin-bottom: 0 !important; }
.author-note { color: var(--muted); font-size: 14px; }
@media (max-width: 767px) { .well .row > .col-sm-6 { width: 50%; float: left; }
  .well .row > .col-sm-7 { width: 58.33%; float: left; } .well .row > .col-sm-5 { width: 41.67%; float: left; } }
@media (max-width: 520px) { .author-card { flex-direction: column; text-align: center; } }

/* Getting started as a slim step indicator: numbered steps in a row joined by a line */
.howto {   padding: 10px 36px 10px 14px; }
.howto-title {  text-transform: uppercase;   margin-bottom: 8px; }
.howto-step {     position: relative; }
.howto-note { margin-top: 8px; color: var(--muted); }

/* Reserve the bold width in every tab so selecting one never moves the others */
.nav-tabs > li > a::after { content: attr(data-value); display: block; height: 0; overflow: hidden;
  visibility: hidden; font-weight: 600; }
#tabs > li > a[data-value='Forecast']::after, #tabs > li > a[data-value='Sensitivity']::after,
#tabs > li > a[data-value='Assumption draws']::after, #tabs > li > a[data-value='Survival curves']::after { padding-left: 17px; }
/* Out-of-date results: the Run button turns amber */
#run.stale { background: #f2b233; border-color: #c98a0a; color: #3a2600; }
#run.stale:hover, #run.stale:focus { background: #e6a31f; border-color: #b57a05; color: #3a2600; }
.card-legend.on { grid-template-rows: 1fr; opacity: 1; }
.card-legend span { display: none; }
.card-legend span.on { display: inline; animation: fade-in var(--dur) ease-out; }

/* Tighter tabs so the bar rarely wraps (a wrap makes the content jump when the settings panel slides) */
.nav-tabs > li > a { padding: 8px 12px; }
@media (max-width: 1250px) { .nav-tabs > li > a { padding: 8px 9px; font-size: 13.5px; } }

/* Variable letters on the cards look like the ones in the equations */
.mvar { font-family: 'Times New Roman', Times, serif; font-style: italic; font-weight: 400; font-size: 1.2em; padding: 0 1px; }
/* Preset descriptions: stacked in one box whose height eases to the visible one */
.preset-stack { position: relative; }
.preset-stack.animate { transition: height var(--dur) cubic-bezier(.4,0,.2,1); }
.preset-pane { position: absolute; top: 0; left: 0; right: 0; opacity: 0; visibility: hidden;
  transition: opacity var(--dur-fast) ease, visibility 0s linear var(--dur-fast); }
.preset-pane.on { opacity: 1; visibility: visible; transition: opacity var(--dur) ease var(--dur-fast), visibility 0s; }
.preset-stack.ready { height: auto; }

.bulk-note { font-size: 12.5px; color: var(--warn); display: grid; grid-template-rows: 0fr; opacity: 0;
  transition: grid-template-rows var(--dur) ease, opacity var(--dur) ease; }
.bulk-note-in { overflow: hidden; min-height: 0; padding-bottom: 0; transition: padding-bottom var(--dur) ease; }
.bulk-note.on { grid-template-rows: 1fr; opacity: 1; }
.bulk-note.on .bulk-note-in { padding-bottom: 10px; }
.preset-vary { font-size: 12.5px; color: var(--muted); margin: 0 0 8px; min-height: 18px; }
.preset-vary .was { color: var(--warn); animation: fade-in var(--dur) ease-out; }
/* Phones: keep the tabs on one swipeable row instead of wrapping into three */
@media (max-width: 767px) {
  .nav-tabs { display: flex; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
  .nav-tabs::-webkit-scrollbar { display: none; }
  .nav-tabs > li { float: none; flex: none; white-space: nowrap; }
}
/* Getting started: each step is as wide as its text and the free space is split evenly between them,
   so the three fill the box with equal gaps (one column on narrow screens) */
.howto-steps { display: flex; flex-wrap: nowrap; justify-content: space-between; gap: 10px 24px; }
.howto-step { flex: 0 1 auto; padding-right: 0; }
@media (max-width: 640px) { .howto-steps { flex-direction: column; } }

/* Getting started is hidden with a small arrow tab on its bottom edge; hover or focus it to see "Hide" */
.howto {  padding-bottom: 20px; }
.howto-close { position: absolute; top: auto; right: auto; bottom: -11px; left: 50%; transform: translateX(-50%); width: auto; height: 22px;
  display: flex; align-items: center; justify-content: center; gap: 0; padding: 0 16px; border: 1px solid var(--line-strong); border-radius: 11px;
   color: var(--accent-dark); font-size: 12px; line-height: 1; cursor: pointer; box-shadow: 0 1px 3px rgba(16,24,40,0.12);
  transition: background-color var(--dur-fast) ease, border-color var(--dur-fast) ease, padding var(--dur) ease, gap var(--dur) ease; }
.howto-close .x { display: none; }
.howto-close::before { content: ""; width: 6px; height: 6px; flex: none; border-left: 2px solid currentColor; border-top: 2px solid currentColor;
  transform: rotate(45deg); margin-top: 3px; }
.howto-close .lbl { display: block; max-width: 0; overflow: hidden; white-space: nowrap; opacity: 0; font-size: 12px; font-weight: 600;
  transition: max-width var(--dur) ease, opacity var(--dur-fast) ease; }
.howto-close:hover, .howto-close:focus-visible { background: var(--accent-soft); border-color: var(--accent); gap: 7px; padding: 0 14px 0 16px; }
.howto-close:hover .lbl, .howto-close:focus-visible .lbl { max-width: 40px; opacity: 1; }

/* Forecast: headline numbers as tiles */
.stat-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin: 6px 0 8px; align-items: stretch; }
.stat-tile { background: var(--surface); border: 1px solid var(--line); border-radius: 8px; padding: 10px 14px 11px;
  box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
.stat-tile.is-lead { border-color: var(--accent-line); background: var(--accent-soft); }
.tile-label { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; }
.tile-value { font-size: 24px; font-weight: 600; line-height: 1.25; color: var(--text); font-variant-numeric: tabular-nums; }
.stat-tile.is-lead .tile-value { color: var(--accent-dark); }
.tile-sub { font-size: 12px; color: var(--muted); }
.sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); border: 0; }
.plot-card { background: var(--surface); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px 4px; margin: 10px 0 14px;
  box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
.plot-controls { display: flex; flex-wrap: wrap; gap: 0 14px; }
.plot-controls .form-group { margin-bottom: 8px; }
.plot-controls label { font-size: 12.5px; color: var(--muted); }
.plot-card .dl-row { margin: 6px 0 8px; }
/* Statistics table */
.stats-table table.table, .clean-table table.table { width: 100%; max-width: 440px; border-collapse: collapse; font-size: 13.5px; background: var(--surface);
  border: 1px solid var(--line); border-radius: 6px; overflow: hidden; }
.stats-table th, .clean-table th { background: var(--accent-soft); color: var(--accent-dark); font-weight: 600; text-align: left;
  padding: 6px 12px; border-bottom: 1px solid var(--accent-line); }
.stats-table th:last-child, .stats-table td:last-child { text-align: right; font-variant-numeric: tabular-nums; }
.stats-table td, .clean-table td { padding: 5px 12px; border-top: 1px solid var(--line); }
.stats-table tr:first-child td, .clean-table tr:first-child td { border-top: 0; }
.stats-table tbody tr:hover td, .clean-table tbody tr:hover td { background: var(--surface-2); }
/* Loading: a soft shimmer behind results that are being recalculated */
.shiny-plot-output.recalculating { background: linear-gradient(90deg, var(--shimmer-a) 25%, var(--shimmer-b) 50%, var(--shimmer-a) 75%);
  background-size: 200% 100%; animation: shimmer 1.3s linear infinite; border-radius: 6px; }
.stat-tiles { transition: opacity var(--dur) ease; }
.recalculating .stat-tile { animation: tile-pulse 1.1s ease-in-out infinite; }
@keyframes shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
@keyframes tile-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
/* A card with a problem: red edge and tint, and a brief pulse when Run is blocked */
.assump-card.assump-invalid { border-left: 3px solid var(--danger); background: var(--danger-bg); }
.assump-card.err-pulse { animation: err-pulse 1.2s ease-out 2; }
@keyframes err-pulse { 0% { box-shadow: 0 0 0 0 rgba(192,57,43,0.45); } 70%, 100% { box-shadow: 0 0 0 10px rgba(192,57,43,0); } }

/* Sensitivity */
.tab-lead { font-size: 14px; color: var(--muted); margin: 6px 0 4px; }
.tile-name { font-size: 14px; font-weight: 600; line-height: 1.25; margin: 2px 0 0; }
.tile-sub.up { color: var(--accent-dark); }
.tile-sub.down { color: var(--amber-text); }
.how-to-read { margin: 4px 0 10px; font-size: 13px; color: var(--muted); }
.how-to-read summary { cursor: pointer; color: var(--accent-dark); width: max-content; }
.how-to-read p { margin: 6px 0 0; max-width: 760px; line-height: 1.45; }
/* Metric picker as a segmented control */
.seg-wrap .form-group { margin-bottom: 8px; }
.seg-wrap .shiny-options-group { display: inline-flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: var(--surface-2); }
.seg-wrap .radio-inline { margin: 0 !important; padding: 0 !important; }
.seg-wrap .radio-inline input { position: absolute; opacity: 0; pointer-events: none; }
.seg-wrap .radio-inline span { display: block; padding: 6px 14px; font-size: 13px; color: var(--muted); cursor: pointer;
  transition: background-color var(--dur-fast) ease, color var(--dur-fast) ease; }
.seg-wrap .radio-inline + .radio-inline span { border-left: 1px solid var(--line); }
.seg-wrap .radio-inline:hover span { background: var(--accent-soft); }
.seg-wrap .radio-inline input:checked + span { background: var(--btn); color: #fff; font-weight: 600; }
.seg-wrap .radio-inline input:focus-visible + span { outline: 2px solid var(--accent); outline-offset: -2px; }

/* Preset buttons: one line each, with no wasted padding */
.preset-vary { margin-bottom: 6px; }

/* Preset: two side-by-side segments */
#preset .shiny-options-group { display: flex; gap: 0; }
#preset .radio { flex: 1 1 0; margin: 0; }
#preset .radio label span { text-align: center; border-radius: 0; padding: 5px 4px; }
#preset .radio:first-child label span { border-radius: 4px 0 0 4px; }
#preset .radio:last-child label span { border-radius: 0 4px 4px 0; border-left-width: 0; }
#preset input:checked + span::before { content: none; }
#preset input:checked + span { font-weight: 600; }

/* Assumption draws */
.draws-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; margin: 8px 0 12px; }
.draws-count { font-size: 12.5px; color: var(--muted); margin-right: auto; }
.seg-js { display: inline-flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: var(--surface-2); }
.seg-js button { border: 0; background: none; padding: 5px 14px; font-size: 13px; color: var(--muted); cursor: pointer;
  transition: background-color var(--dur-fast) ease, color var(--dur-fast) ease; }
.seg-js button + button { border-left: 1px solid var(--line); }
.seg-js button:hover { background: var(--accent-soft); }
.seg-js button.on { background: var(--btn); color: #fff; font-weight: 600; }
.draw-tile { position: relative; padding: 6px 6px 8px; border-radius: 10px; box-shadow: 0 1px 2px rgba(16,24,40,0.04);
  transition: box-shadow var(--dur-fast) ease, border-color var(--dur-fast) ease, transform var(--dur-fast) ease; }
.draw-tile:hover, .draw-tile:focus-visible { transform: translateY(-2px); box-shadow: 0 6px 16px rgba(16,24,40,0.12); }
.draw-zoom { position: absolute; top: 9px; right: 10px; z-index: 2; font-size: 12px; color: var(--muted);
  opacity: 0; transition: opacity var(--dur-fast) ease; }
.draw-tile:hover .draw-zoom, .draw-tile:focus-visible .draw-zoom { opacity: 1; }
.draw-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 2px 8px 0; }
.draw-stats { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; }
.draw-badge { font-size: 11px; font-weight: 600; border-radius: 9px; padding: 1px 8px; white-space: nowrap; }
.draw-badge.vary { background: var(--accent-soft); color: var(--accent-dark); }
.draw-badge.fixed { background: var(--surface-3); color: var(--muted); }

.tab-content > .tab-pane.leaving { display: none !important; }

/* Model check */
.mc-head { margin: 18px 0 2px; font-weight: 600; }
.mc-head:first-child { margin-top: 8px; }
.mc-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 10px 0 6px; }
.mc-actions .btn { margin: 0; }
.clean-table table.table { width: 100%; max-width: none; font-size: 12.5px; }
.clean-table th { white-space: normal; vertical-align: bottom; line-height: 1.25; }
.clean-table td:not(:first-child), .clean-table th:not(:first-child) { text-align: right; }
.clean-table.two-text td:nth-child(2), .clean-table.two-text th:nth-child(2) { text-align: left; }
.plot-placeholder { text-align: center; color: var(--muted); padding: 60px 20px; border: 1px dashed var(--line-strong); border-radius: 8px; margin-bottom: 10px; }

/* About */
.about { max-width: 860px; }
.about-card { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 18px 24px 8px; margin: 0 0 14px;
  box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
.about-card h4 { margin: 0 0 10px; font-size: 18px; }
.about-card p, .about-card li { line-height: 1.55; }
.about-lead { font-size: 15.5px; color: var(--text); }
.about-card ul { padding-left: 20px; }
.about-card ul li { margin-bottom: 9px; }
.about-card ul li > strong:first-child { color: var(--accent-dark); }
.about-refs { padding-left: 22px; }
.about-refs li { margin-bottom: 10px; padding-left: 4px; }
.about-refs li::marker { color: var(--muted); font-weight: 600; }
.about .fold { margin: 6px 0 14px; padding: 4px 12px; background: var(--page); border: 1px solid var(--line); border-radius: 8px; }
.about .app-meta { margin: 0 0 14px; }
.about .author-card { max-width: none; margin-bottom: 20px; background: var(--surface); box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
.about-section { scroll-margin-top: 54px; }

.stale-ghost { font-size: 12px; color: var(--warn); background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 4px; padding: 5px 8px; margin-top: 8px; }
.cite-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; margin: 0 0 14px; }
.cite-row .app-meta { margin-right: auto; }
.cite-row .btn { margin: 0; }

/* Theme toggle and logo swap */
.app-brand { position: relative; }
.theme-toggle { position: absolute; right: 0; top: 50%; transform: translateY(-50%); width: 34px; height: 34px; border-radius: 50%;
  border: 1px solid var(--line-strong); background: var(--surface); color: var(--muted); cursor: pointer; font-size: 14px;
  transition: background-color var(--dur-fast) ease, color var(--dur-fast) ease, border-color var(--dur-fast) ease; }
.theme-toggle:hover { background: var(--hover); color: var(--text); }
.theme-toggle .fa-moon { display: inline-block; } .theme-toggle .fa-sun { display: none; }
html[data-theme="dark"] .theme-toggle .fa-moon { display: none; } html[data-theme="dark"] .theme-toggle .fa-sun { display: inline-block; }
.logo-dark, html[data-theme="dark"] .logo-light { display: none; }
html[data-theme="dark"] .logo-dark { display: block; }
html[data-theme="dark"] .app-mosquito { filter: brightness(1.5) saturate(0.9); }
body, .well, .form-control, .selectize-input, .btn, .nav-tabs > li > a, .stat-tile, .plot-card, .about-card, .draw-tile, .assump-card {
  transition-property: background-color, border-color, color, box-shadow, opacity, transform; transition-duration: var(--dur); }
/* Dark theme: Bootstrap and Shiny widgets that set their own light colours */
html[data-theme="dark"] body { background: var(--page); color: var(--text); }
html[data-theme="dark"] .form-control, html[data-theme="dark"] .selectize-input, html[data-theme="dark"] .selectize-dropdown,
html[data-theme="dark"] .selectize-control.single .selectize-input { background: var(--surface-2); color: var(--text); border-color: var(--line-strong); box-shadow: none; }
html[data-theme="dark"] .selectize-input input { color: var(--text); }
html[data-theme="dark"] .selectize-dropdown .option { color: var(--text); }
html[data-theme="dark"] .selectize-dropdown .active { background: var(--accent-soft); color: var(--text); }
html[data-theme="dark"] .selectize-input.dropdown-active::before { background: none; }
html[data-theme="dark"] .form-control::placeholder { color: var(--faint); }
html[data-theme="dark"] .btn-default { background: var(--surface); color: var(--text); border-color: var(--line-strong); }
html[data-theme="dark"] .btn-default:hover, html[data-theme="dark"] .btn-default:focus, html[data-theme="dark"] .btn-default:active { background: var(--hover); color: var(--text); border-color: var(--line-strong); }
html[data-theme="dark"] .nav-tabs { border-bottom-color: var(--line); }
html[data-theme="dark"] .nav-tabs > li > a { border-color: transparent; }
html[data-theme="dark"] .nav-tabs > li > a:hover { background: var(--accent-soft); border-color: var(--line) var(--line) transparent; color: var(--text); }
html[data-theme="dark"] .table, html[data-theme="dark"] table { color: var(--text); }
html[data-theme="dark"] .table > thead > tr > th, html[data-theme="dark"] .table > tbody > tr > td { border-color: var(--line); }
html[data-theme="dark"] hr { border-color: var(--line); }
html[data-theme="dark"] .help-block, html[data-theme="dark"] .text-muted { color: var(--muted); }
