html[data-theme="dark"] .shiny-notification-error { background: var(--danger-bg); color: var(--danger-text); border-color: var(--danger); }
html[data-theme="dark"] .shiny-notification-message { background: var(--surface-2); }
html[data-theme="dark"] .progress { background: var(--surface-3); }
html[data-theme="dark"] .btn-file, html[data-theme="dark"] .settings-io .btn-file { background: var(--surface); color: var(--text); border-color: var(--line-strong); }
html[data-theme="dark"] .well a:not(.btn) { color: var(--accent); }
html[data-theme="dark"] .app-brand-text { color: var(--text); }
html[data-theme="dark"] .jump-chip { background: var(--surface); }
html[data-theme="dark"] .jump-chip:hover { background: var(--hover); }
html[data-theme="dark"] .assump-warn, html[data-theme="dark"] .assump-note { color: var(--warn); }
html[data-theme="dark"] .stat-tile.is-lead .tile-value { color: var(--accent-dark); }
html[data-theme="dark"] #sens_top .tile-sub.down { color: var(--amber-text); }
html[data-theme="dark"] .shiny-plot-output img, html[data-theme="dark"] .draw-tile img { border-radius: 4px; }
html[data-theme="dark"] .app-footer { color: var(--muted); }
html[data-theme="dark"] .compare-table th, html[data-theme="dark"] .compare-table td { border-color: var(--line); }
html[data-theme="dark"] .compare-table th { background: var(--surface-2); }
html[data-theme="dark"] .btn-primary, html[data-theme="dark"] .btn-default.btn-primary { background: var(--btn); border-color: var(--btn-dark); color: #fff; }
html[data-theme="dark"] .btn-primary:hover, html[data-theme="dark"] .btn-default.btn-primary:hover,
html[data-theme="dark"] .btn-primary:focus, html[data-theme="dark"] .btn-default.btn-primary:focus { background: var(--btn-dark); color: #fff; }
html[data-theme="dark"] #run.stale { background: #f2b233; border-color: #c98a0a; color: #3a2600; }

/* Tabs: a tinted strip with a raised, accent-topped active tab so they stand out from the page */
#tabs.nav-tabs { border-bottom: 1px solid var(--line-strong); }
#tabs.nav-tabs > li > a { background: var(--surface-3); border: 1px solid var(--line); border-bottom-color: var(--line-strong);
  margin-right: 3px; color: var(--muted); }
#tabs.nav-tabs > li > a:hover { background: var(--accent-soft); border-color: var(--accent-line); border-bottom-color: var(--line-strong); color: var(--text); }
#tabs.nav-tabs > li.active > a, #tabs.nav-tabs > li.active > a:hover, #tabs.nav-tabs > li.active > a:focus {
  background: var(--surface); color: var(--accent-dark); font-weight: 600;
  border-color: var(--line-strong) var(--line-strong) var(--surface); border-top: 3px solid var(--accent);
  padding-top: 6px; box-shadow: 0 -2px 6px rgba(16,24,40,0.06); }

/* Run button progress fill. Placed last with extra specificity so it beats .stale and .btn-primary states */
#run.btn.running, #run.btn.running.stale, #run.btn.running:disabled {
  background-color: var(--btn); border-color: var(--btn-dark); color: #fff; opacity: 1;
  background-image: linear-gradient(90deg, rgba(255,255,255,0.32) var(--p, 0%), rgba(255,255,255,0) var(--p, 0%)); }
.shiny-progress-notification:not(.keep-progress) { display: none; }

/* Run options, reset menu, compare runs, probability readout, busy state */
.run-options, .reset-menu { margin: 0 0 10px; }
.run-options > summary, .reset-menu > summary { cursor: pointer; font-size: 13px; font-weight: 600; color: var(--muted); margin-bottom: 6px; }
.run-options-hint { font-weight: 400; font-size: 12px; opacity: .8; }
.reset-menu { font-size: 12px; }
.compare-runs { margin: 10px 0 14px; }
.compare-runs > summary { cursor: pointer; font-weight: 600; }
.cert-readout { background: var(--accent-soft); border: 1px solid var(--accent-line); border-radius: 6px; padding: 6px 12px; margin: 0 0 10px; }
.cert-readout p { margin: 2px 0; font-size: 14px; }
.cert-readout strong { font-size: 17px; color: var(--accent-dark); font-variant-numeric: tabular-nums; }
body.is-busy .results-body { opacity: .5; transition: opacity var(--dur-fast) ease; pointer-events: none; }
body.is-busy #run { cursor: progress; }
body.is-busy #run::after { content: ""; display: inline-block; width: 14px; height: 14px; margin-left: 8px; vertical-align: -2px;
  border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: pvec-spin .7s linear infinite; }
@keyframes pvec-spin { to { transform: rotate(360deg); } }

/* Collapsible sections that look like buttons, with a chevron that turns when open */
.run-options > summary, .compare-runs > summary, .reset-menu > summary {
  list-style: none; display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%;
  box-sizing: border-box; padding: 7px 12px; margin-bottom: 8px; cursor: pointer; user-select: none;
  background: var(--surface); color: var(--accent-dark); border: 1px solid var(--line); border-radius: 6px;
  font-size: 13px; font-weight: 600; }
.compare-runs > summary { width: max-content; min-width: 200px; font-size: 13px; }
.run-options > summary::-webkit-details-marker, .compare-runs > summary::-webkit-details-marker,
.reset-menu > summary::-webkit-details-marker { display: none; }
.run-options > summary::after, .compare-runs > summary::after, .reset-menu > summary::after {
  content: ""; width: 7px; height: 7px; flex: none; margin: -3px 2px 0 6px;
  border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(45deg); transition: transform var(--dur-fast) ease; }
.run-options[open] > summary::after, .compare-runs[open] > summary::after, .reset-menu[open] > summary::after {
  transform: rotate(-135deg); margin-top: 3px; }
.run-options > summary:hover, .compare-runs > summary:hover, .reset-menu > summary:hover { background: var(--accent-soft); border-color: var(--accent-line); }
.run-options > summary:focus-visible, .compare-runs > summary:focus-visible, .reset-menu > summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* The whole section is one box: the button is its header and the content drops down inside it */
.run-options, .compare-runs { border: 1px solid var(--line); border-radius: 6px; background: var(--surface); }
.run-options > summary, .compare-runs > summary { border: 0; border-radius: 6px; margin-bottom: 0; background: transparent; }
.run-options[open] > summary, .compare-runs[open] > summary { border-bottom: 1px solid var(--line); border-radius: 6px 6px 0 0; }
.compare-runs { width: max-content; max-width: 100%; }
.dd-body { padding: 10px 12px 2px; animation: dd-drop var(--dur-fast) ease-out; }
.dd-body .form-group { margin-bottom: 8px; }
@keyframes dd-drop { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }

/* Mortality model and age structure as visible choice buttons, like the preset */
#mort_model > label.control-label { display: block; margin-bottom: 4px; }
#mort_model .shiny-options-group { margin-top: 0; }
#mort_model .radio label { display: block; padding: 0; width: 100%; }
#mort_model input[type=radio] { position: absolute; opacity: 0; pointer-events: none; }
#mort_model .radio label span { display: block;   border: 1px solid var(--line-strong);
   background: var(--surface); color: var(--text); cursor: pointer; }
#mort_model .radio label:hover span { background: var(--hover); }
#mort_model .radio label:hover input:checked + span { background: var(--btn-dark); }
#mort_model input:checked + span { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
#mort_model input:checked + span::before {  font-weight: bold; }
#mort_model input:focus-visible + span { outline: 2px solid #66afe9; outline-offset: 1px; }
#structure > label.control-label { display: block; margin-bottom: 4px; }
#structure .shiny-options-group { margin-top: 0; }
#structure .radio label { display: block; padding: 0; width: 100%; }
#structure input[type=radio] { position: absolute; opacity: 0; pointer-events: none; }
#structure .radio label span { display: block;  font-size: 13px; border: 1px solid var(--line-strong);
   background: var(--surface); color: var(--text); cursor: pointer; }
#structure .radio label:hover span { background: var(--hover); }
#structure .radio label:hover input:checked + span { background: var(--btn-dark); }
#structure input:checked + span { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
#structure input:checked + span::before {  font-weight: bold; }
#structure input:focus-visible + span { outline: 2px solid #66afe9; outline-offset: 1px; }
#mort_model .shiny-options-group { display: flex; gap: 0; }
#mort_model .radio { flex: 1 1 0; margin: 0; }
#mort_model .radio label span { text-align: center; border-radius: 0;  }
#mort_model .radio:first-child label span { border-radius: 4px 0 0 4px; }
#mort_model .radio:last-child label span { border-radius: 0 4px 4px 0; border-left-width: 0; }
#mort_model input:checked + span::before { content: none; }
#mort_model input:checked + span { font-weight: 600; }
#mort_model .radio label span { font-size: 12px; padding: 5px 2px; }
#mort_model, #structure { margin-bottom: 10px; }
#mort_model .radio:not(:first-child) label span { border-left-width: 0; }
#mort_model .radio:not(:first-child):not(:last-child) label span { border-radius: 0; }
#structure input:checked + span::before { content: none; }

/* Sidebar "Trials and seed": same look as the other sidebar labels (flat, flush left, same font and colour) */
.well .run-options { border: 0; background: transparent; border-radius: 0; margin: 0 0 8px; }
.well .run-options > summary, .well .run-options[open] > summary { padding: 0; margin: 0 0 2px; border: 0; border-radius: 0; background: transparent;
  color: var(--text); font-size: 13px; font-weight: 700; width: 100%; }
.well .run-options > summary:hover { background: transparent; color: var(--accent-dark); }
.well .run-options .dd-body { padding: 0; animation: none; }

/* Age structure: side-by-side segments like the preset */
#structure .shiny-options-group { display: flex; gap: 0; }
#structure .radio { flex: 1 1 0; margin: 0; }
#structure .radio label span { text-align: center; border-radius: 0; padding: 5px 4px; }
#structure .radio:first-child label span { border-radius: 4px 0 0 4px; }
#structure .radio:last-child label span { border-radius: 0 4px 4px 0; border-left-width: 0; }
#structure input:checked + span { font-weight: 600; }

/* Small "?" help bubble next to a label; the explanation appears on hover or keyboard focus */
.help-tip { position: relative; display: inline-flex; align-items: center; justify-content: center; width: 15px; height: 15px; margin-left: 2px;
  border: 1.5px solid var(--muted); border-radius: 50%; color: var(--muted); font-size: 10px; font-weight: 700; line-height: 1; cursor: help; vertical-align: 1px; }
.help-tip:hover, .help-tip:focus { color: var(--accent-dark); border-color: var(--accent-dark); outline: none; }
.help-tip-text { display: none; position: fixed; z-index: 2000; left: 0; top: 0; width: 260px; padding: 8px 10px; text-align: left;
  background: var(--surface); color: var(--text); border: 1px solid var(--line-strong); border-radius: 6px; box-shadow: 0 4px 14px rgba(16,24,40,.18);
  font-size: 12px; font-weight: 400; line-height: 1.4; }
.help-tip:hover .help-tip-text, .help-tip:focus .help-tip-text { display: block; }

/* Trials box: arrow buttons drawn to look like the number-box spinner */
.trials-box .form-group, #seed { position: relative; }
.stepper-btns { position: absolute; right: 1px; bottom: 1px; width: 18px; height: 28px; display: flex; flex-direction: column; opacity: 0; transition: opacity var(--dur-fast); }
.form-group:hover > .stepper-btns, .form-group:focus-within > .stepper-btns { opacity: 1; }
#seed::-webkit-inner-spin-button, #seed::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
#seed { -moz-appearance: textfield; appearance: textfield; }
.stepper-btns button { flex: 1; border: 0; padding: 0; background: transparent; cursor: pointer; position: relative; color: var(--muted); }
.stepper-btns button:hover { background: var(--hover); color: var(--text); }
.stepper-btns button::after { content: ""; position: absolute; left: 50%; top: 50%; width: 4px; height: 4px; margin: -3px 0 0 -3px;
  border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; transform: rotate(-135deg); }
.stepper-btns .down::after { transform: rotate(45deg); margin-top: -4px; }

/* The progress pop-up is replaced by the fill inside the Run button, so hide its empty outer box too */
.shiny-notification:has(.shiny-progress-notification:not(.keep-progress)) { display: none; }
/* The "Run N finished" box waits until the fill inside the Run button has completed */
body:has(#run.running) .shiny-notification-message { display: none; }
.shiny-notification-message { animation: fade-in var(--dur) ease-out; }

/* Run history: a button under the status line that drops down the last 5 run messages inside the dock */
.run-history { margin-top: 8px; }
.run-history > summary { list-style: none; display: flex; align-items: center; justify-content: space-between; cursor: pointer; user-select: none;
  padding: 5px 10px; font-size: 12.5px; font-weight: 600; color: var(--accent-dark);
    }
.run-history > summary::-webkit-details-marker { display: none; }
.run-history > summary:hover { background: var(--accent-soft); border-color: var(--accent-line); }
.run-history > summary::after { content: ""; width: 6px; height: 6px; flex: none; margin: -3px 2px 0 6px;
  border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(45deg); transition: transform var(--dur-fast) ease; }
.run-history[open] > summary::after { transform: rotate(-135deg); margin-top: 3px; }
.run-history-list { list-style: none;   animation: fade-in var(--dur-fast) ease-out; }
.run-history-list li { font-size: 11.5px; line-height: 1.35; color: var(--muted); padding: 5px 2px; border-top: 1px solid var(--line); }
.run-history-list li:first-child { border-top: 0; color: var(--text); }
.run-history-list li.empty { font-style: italic; }

/* Status line crossfade: the old message fades out beneath the new one as it fades in */
.run-status { position: relative; }
.run-status .status-in { animation: status-in 1.2s ease-in-out backwards; }
.run-status .status-ghost { position: absolute; left: 0; right: 0; top: 0; animation: status-out 1.2s ease-in-out both; pointer-events: none; }
@keyframes status-in { 0% { opacity: 0; color: var(--accent-dark); } 100% { opacity: 1; } }
@keyframes status-out { 0% { opacity: 1; } 100% { opacity: 0; } }

/* Cleaner cards: tighter spacing, preview lined up under the title text */
.cards-grid .assump-card { padding: 10px 14px 8px; }
.assump-summary { margin: 2px 0 0 16px; }
.cards-grid .assump-prev { margin: 2px 0 0 16px; }

/* Run context line, stale warning, metric caption */
.run-context { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; margin: 0 0 8px; min-height: 24px; font-size: 12.5px; color: var(--muted); }
.rc-main { font-weight: 600; color: var(--text); }
.rc-stale { color: var(--warn); background: var(--warn-bg); border: 1px solid var(--warn-line); border-radius: 9px; padding: 1px 10px; }
.rc-stale a { font-weight: 600; }
.metric-caption { font-size: 12.5px; color: var(--muted); margin: 2px 0 8px; max-width: 760px; }

/* "How to read" as a button with a ? at the start */
.how-to-read:not(.compare-runs) > summary { list-style: none; display: inline-flex; align-items: center; gap: 7px; cursor: pointer; user-select: none;
  padding: 3px 10px 3px 6px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface); color: var(--accent-dark); font-weight: 600; }
.how-to-read:not(.compare-runs) > summary::-webkit-details-marker { display: none; }
.how-to-read:not(.compare-runs) > summary::before { content: "?"; display: inline-flex; align-items: center; justify-content: center; width: 16px; height: 16px;
  border: 1.5px solid currentColor; border-radius: 50%; font-size: 10px; font-weight: 700; line-height: 1; }
.how-to-read:not(.compare-runs) > summary:hover { background: var(--accent-soft); border-color: var(--accent-line); }
.how-to-read:not(.compare-runs)[open] > summary { background: var(--accent-soft); border-color: var(--accent-line); }

/* Download menu */
.dl-menu .dropdown-menu { font-size: 13px; min-width: 190px; }
.dl-menu .dropdown-menu a { cursor: pointer; }
html[data-theme="dark"] .dl-menu .dropdown-menu { background: var(--surface); border-color: var(--line-strong); }
html[data-theme="dark"] .dl-menu .dropdown-menu > li > a { color: var(--text); }
html[data-theme="dark"] .dl-menu .dropdown-menu > li > a:hover { background: var(--accent-soft); }

/* Clickable forecast chart, driver tiles, sort buttons, compact fixed cards, survival hover tip */
#forecast_plot { cursor: crosshair; }
.driver-tile { cursor: pointer; transition: box-shadow var(--dur-fast) ease, transform var(--dur-fast) ease, border-color var(--dur-fast) ease; }
.driver-tile:hover, .driver-tile:focus-visible { box-shadow: 0 4px 12px rgba(16,24,40,0.14); transform: translateY(-1px); border-color: var(--accent); }
.seg-sort { display: inline-flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: var(--surface-2); }
.seg-sort button { border: 0; background: none; padding: 5px 12px; font-size: 13px; color: var(--muted); cursor: pointer; }
.seg-sort button + button { border-left: 1px solid var(--line); }
.seg-sort button:hover { background: var(--accent-soft); }
.seg-sort button.on { background: var(--btn); color: #fff; font-weight: 600; }
.draw-tile.is-fixed { align-self: start; padding-bottom: 6px; }
.fixed-row { display: flex; flex-direction: column; gap: 2px; padding: 8px 8px 6px; }
.fixed-row strong { font-size: 14px; }
.fixed-val { font-size: 13px; color: var(--accent-dark); font-variant-numeric: tabular-nums; }
.tip-cell { position: relative; }
.tip-cell .surv-tip { left: calc(var(--tx, 0px) + 14px); top: calc(var(--ty, 0px) + 14px); }
.tip-cell.tip-flip .surv-tip { left: calc(var(--tx, 0px) - 14px); transform: translateX(-100%); }
.tip-cell:not(:hover) .surv-tip { display: none; }
.surv-tip .tip-hint { color: var(--muted, #6b7280); font-size: 11px; margin-top: 2px; }
.surv-tip { position: absolute; z-index: 30; pointer-events: none; background: var(--surface); color: var(--text); border: 1px solid var(--line-strong);
  border-radius: 6px; padding: 6px 10px; font-size: 12px; line-height: 1.4; box-shadow: 0 4px 14px rgba(16,24,40,.18); white-space: nowrap; }

.surv-wrap { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 10px; }
.surv-cell { position: relative; min-width: 0; }
@media (max-width: 700px) { .surv-wrap { grid-auto-flow: row; } }

/* The "settings changed" chip fades in; the line already has its height, so nothing moves */
.rc-stale { animation: chip-in .5s ease both; line-height: 1.3; }
@keyframes chip-in { from { opacity: 0; } to { opacity: 1; } }

/* Run button label: fades out, swaps and fades in */
#run .run-label {  transition: opacity var(--dur) ease; }
#run .run-label.fading { opacity: 0; }

/* Reset button and its pop-up choices */
.reset-open { margin: 0 0 6px; }
.reset-option { display: block; width: 100%; text-align: left; white-space: normal; padding: 10px 14px; margin: 0 0 10px; background: var(--surface);
  border: 1px solid var(--line-strong); border-radius: 8px; color: var(--text); transition: background-color var(--dur-fast), border-color var(--dur-fast), box-shadow var(--dur-fast); }
.reset-option:hover, .reset-option:focus { background: var(--accent-soft); border-color: var(--accent); box-shadow: 0 2px 8px rgba(16,24,40,0.12); color: var(--text); }
.ro-title { font-weight: 600; font-size: 14px; color: var(--accent-dark); }
.ro-desc { font-size: 12.5px; color: var(--muted); margin-top: 2px; font-weight: 400; }

/* Run history as one box: the header button on top, the list dropping down inside it */
.run-history { border: 1px solid var(--line); border-radius: 6px; background: var(--surface); }
.run-history > summary { border: 0; border-radius: 6px; background: transparent; }
.run-history[open] > summary { border-bottom: 1px solid var(--line); border-radius: 6px 6px 0 0; }
.run-history-list { margin: 0; padding: 2px 10px 4px; }

/* Wipe between the blue and amber Run button: the new face slides in from the left */
#run.no-trans, #run.no-trans * { transition: none !important; }
@property --wa { syntax: '<angle>'; inherits: false; initial-value: 0deg; }
.run-wipe { position: absolute; top: -1px; right: -1px; bottom: -1px; left: -1px; display: flex; align-items: center; justify-content: center;
  border-radius: inherit; pointer-events: none; }
.run-wipe.to-stale { --wa: 0deg; --pv: 200px; --hr: 35deg; --fe: 45deg;
  -webkit-mask-image: conic-gradient(from calc(0deg - var(--hr)) at 50% var(--pv), #000 calc(var(--wa) - var(--fe)), transparent var(--wa));
  mask-image: conic-gradient(from calc(0deg - var(--hr)) at 50% var(--pv), #000 calc(var(--wa) - var(--fe)), transparent var(--wa)); }
.run-wipe.to-fresh { --wa: -45deg; --pv: 200px; --hr: 35deg; --fe: 45deg;
  -webkit-mask-image: conic-gradient(from calc(0deg - var(--fe) - var(--hr)) at 50% var(--pv), transparent calc(2 * var(--hr) - var(--wa)), #000 calc(2 * var(--hr) + var(--fe) - var(--wa)), #000 360deg);
  mask-image: conic-gradient(from calc(0deg - var(--fe) - var(--hr)) at 50% var(--pv), transparent calc(2 * var(--hr) - var(--wa)), #000 calc(2 * var(--hr) + var(--fe) - var(--wa)), #000 360deg); }
.run-wipe.to-stale { background: #f2b233; color: #3a2600; box-shadow: inset 0 0 0 1px #c98a0a; }
.run-wipe.to-fresh { background: var(--btn); color: #fff; box-shadow: inset 0 0 0 1px var(--btn-dark); }

/* About: one-minute summary, citation card, source links */
.quick-list { margin: 0; padding-left: 20px; }
.quick-list li { margin: 4px 0; }
.cite-text { font-size: 13.5px; color: var(--muted); margin: 4px 0 10px; }
.cite-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.src-uses { margin: 4px 0 6px; font-size: 12.5px; color: var(--muted); display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; }
.src-link { border: 1px solid var(--line-strong); background: var(--surface); color: var(--accent-dark); border-radius: 12px; padding: 1px 10px; font-size: 12px; cursor: pointer;
  transition: background-color var(--dur-fast), border-color var(--dur-fast); }
.src-link:hover { background: var(--accent-soft); border-color: var(--accent); }
.assump-card.card-flash { animation: card-flash 2.2s ease-out; }
@keyframes card-flash { 0%, 30% { box-shadow: 0 0 0 4px var(--accent-line), 0 0 14px 2px var(--accent); } 100% { box-shadow: none; } }

/* Model check marks */
.mc-legend { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 12.5px;  }
.mc-pass { color: #1a7f37; font-weight: 600; }
.mc-warn { color: #9a6700; font-weight: 600; }
.mc-fail { color: #cf222e; font-weight: 600; }
html[data-theme="dark"] .mc-pass { color: #56d364; }
html[data-theme="dark"] .mc-warn { color: #e3b341; }
html[data-theme="dark"] .mc-fail { color: #ff7b72; }

/* Sensitivity bars can be clicked */
#sens_plot { cursor: pointer; }

/* "What this says" box on each results tab, and the highlighted cards at the top of About */
.insight, .about-callout { background: var(--accent-soft); border: 1px solid var(--accent-line); border-left: 4px solid var(--accent); border-radius: 8px; }
.insight {  gap: 12px;  margin: 4px 0 12px; }
.insight-icon { color: var(--accent); font-size: 18px; line-height: 1.5; flex: none; }
.insight-title { font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--accent-dark); margin-bottom: 2px; }
.insight p { margin: 0; font-size: 14px; line-height: 1.5;  }
.about-callout.about-card { background: var(--accent-soft); }
/* Model check key: right-aligned under the table, where the marks appear */
.mc-legend { justify-content: flex-end; margin: 0 0 14px; }
.clean-table + .mc-legend { margin-top: -14px; padding-right: 12px; }

/* Light bulb: a brief yellow glow when its tab is shown */
.insight-icon.glow { animation: bulb-glow 3.6s ease-in-out; }
@keyframes bulb-glow {
  0%   { color: var(--accent); text-shadow: 0 0 0 rgba(242,178,51,0); }
  15%  { color: #e8a317; text-shadow: 0 0 6px rgba(242,178,51,.95), 0 0 16px rgba(242,178,51,.6); }
  70%  { color: #e8a317; text-shadow: 0 0 6px rgba(242,178,51,.95), 0 0 16px rgba(242,178,51,.6); }
  100% { color: var(--accent); text-shadow: 0 0 0 rgba(242,178,51,0); } }

/* When the results are out of date, the light beside each result tab comes on in amber */
body.results-stale #tabs > li > a[data-value='Forecast']::before,
body.results-stale #tabs > li > a[data-value='Sensitivity']::before,
body.results-stale #tabs > li > a[data-value='Assumption draws']::before,
body.results-stale #tabs > li > a[data-value='Survival curves']::before {
  background: #f2b233; border-color: #c98a0a;
  box-shadow: 0 0 0 0 rgba(242,178,51,0), 0 0 6px 2px rgba(242,178,51,0.55);
  transition: background-color .6s ease, border-color .6s ease, box-shadow .6s ease;
  animation: dot-on-amber 1s ease-out 1; }
@keyframes dot-on-amber {
  0%   { transform: scale(.6); box-shadow: 0 0 0 0 rgba(242,178,51,0.7), 0 0 0 0 rgba(242,178,51,0); }
  60%  { transform: scale(1.25); box-shadow: 0 0 0 8px rgba(242,178,51,0), 0 0 6px 2px rgba(242,178,51,0.55); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(242,178,51,0), 0 0 6px 2px rgba(242,178,51,0.55); } }

/* Saved scenarios inside the history box */
.scenarios { border-top: 1px solid var(--line); margin-top: 6px; padding: 8px 10px 6px; }
.scen-title { font-size: 12px; font-weight: 700; color: var(--text); margin-bottom: 4px; }
.scen-save { display: flex; gap: 6px; align-items: flex-start; }
.scen-save .form-group { flex: 1; margin: 0; }
.scen-save .form-control { height: 28px; font-size: 12.5px; }
.scen-empty { font-size: 11.5px; color: var(--muted); margin: 6px 0 2px; line-height: 1.35; }
.scen-list li { border: 1px solid var(--line); border-radius: 6px; padding: 6px 8px; margin: 0 0 6px; background: var(--surface-2); }
.scen-sub { font-size: 11.5px; color: var(--muted); line-height: 1.3; }
.scen-actions { margin-top: 4px; display: flex; gap: 6px; }
.scen-btn { border: 1px solid var(--line-strong); background: var(--surface); color: var(--accent-dark); border-radius: 10px; padding: 1px 9px; font-size: 11.5px; cursor: pointer; }
.scen-btn:hover { background: var(--accent-soft); border-color: var(--accent); }
.scen-btn.del { color: var(--danger); }

/* Most extreme trials table */
.extreme-table { border-collapse: collapse; font-size: 12.5px; width: 100%; }
.extreme-table th { background: var(--accent-soft); color: var(--accent-dark); font-weight: 600; text-align: left; padding: 5px 10px; border-bottom: 1px solid var(--accent-line); vertical-align: bottom; }
.extreme-table td { padding: 5px 10px; border-top: 1px solid var(--line); vertical-align: top; font-variant-numeric: tabular-nums; }
.extreme-table .ex-ct { font-weight: 700; }
.extreme-table .ex-pct { display: block; font-size: 11px; color: var(--muted); }
.extreme-table .ex-cell.lo, .extreme-table .ex-cell.hi { background: rgba(213, 94, 0, 0.12); }
.extreme-table .ex-cell.lo .ex-pct, .extreme-table .ex-cell.hi .ex-pct { color: #b34700; font-weight: 600; }
html[data-theme="dark"] .extreme-table .ex-cell.lo .ex-pct, html[data-theme="dark"] .extreme-table .ex-cell.hi .ex-pct { color: #ff9a57; }
.compare-runs { min-width: 260px; }
.compare-runs .dd-body { min-width: 0; }
.compare-runs[open] { width: 100%; }

/* Guided tour */
.tour-btn { margin: 4px 0 2px; }
.tour-spot { position: fixed; z-index: 3000; border-radius: 10px; pointer-events: none; box-shadow: 0 0 0 9999px rgba(15, 23, 42, 0.55), 0 0 0 3px var(--accent);
  transition: left var(--dur) ease, top var(--dur) ease, width var(--dur) ease, height var(--dur) ease, opacity var(--dur-fast) ease; }
.tour-pop { position: fixed; z-index: 3001; width: 310px; background: var(--surface); color: var(--text); border: 1px solid var(--line-strong); border-radius: 12px;
  padding: 14px 16px; box-shadow: 0 10px 30px rgba(16, 24, 40, 0.35); transition: left var(--dur) ease, top var(--dur) ease; }
.tour-step { font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--accent-dark); }
.tour-title { font-size: 16px; font-weight: 700; margin: 2px 0 4px; }
.tour-text { font-size: 13px; line-height: 1.45; margin: 0 0 12px; color: var(--text); }
.tour-btns { display: flex; align-items: center; gap: 8px; }
.tour-gap { flex: 1; }
.tour-btns button { border-radius: 14px; padding: 4px 14px; font-size: 13px; cursor: pointer; border: 1px solid var(--line-strong); background: var(--surface); color: var(--accent-dark); }
.tour-btns .tour-next { background: var(--btn); border-color: var(--btn-dark); color: #fff; font-weight: 600; }
.tour-btns .tour-skip { border: 0; background: none; color: var(--muted); padding-left: 0; }

/* "What this says": the lightbulb and title always show; the text opens when the box is clicked */
.insight { display: block; padding: 0; }
.insight-head { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 14px; border: 0; background: none; text-align: left; cursor: pointer; color: inherit; border-radius: 8px; }
.insight-head:hover { background: rgba(43, 108, 176, 0.06); }
.insight-head .insight-icon { font-size: 18px; line-height: 1; }
.insight-head .insight-title { margin: 0; flex: 0 0 auto; }
.insight-hint {  font-size: 12px; color: var(--muted); }
.insight-hint::after { content: "View"; }
.insight-open .insight-hint::after { content: "Hide"; }
.insight-chev { width: 7px; height: 7px; margin: -3px 2px 0 6px; flex: none; border-right: 2px solid var(--accent-dark); border-bottom: 2px solid var(--accent-dark);
  transform: rotate(45deg); transition: transform var(--dur-fast) ease; }
.insight-open .insight-chev { transform: rotate(-135deg); margin-top: 3px; }
.insight-body { display: none; padding: 0 14px 12px 42px; }
.insight-open .insight-body { display: block; animation: fade-in var(--dur) ease-out; }
.insight-body p { margin: 0; font-size: 14px; line-height: 1.5; max-width: 860px; }
.insight-body .insight-note { margin-top: 8px; font-size: 12px; color: var(--muted); font-style: italic; }
.insight p { max-width: none; }

/* Past runs: its own box under the Run box */
.history-box { flex: 0 0 auto; margin-top: 10px;   overflow-y: auto; background: var(--surface);
  border: 1px solid var(--line); border-radius: 4px; box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
.history-head { font-weight: 700; font-size: 13.5px; }
.history-sub { font-size: 11.5px; color: var(--muted); margin: 1px 0 8px; line-height: 1.3; }
.scen-list { list-style: none; margin: 0; padding: 0; }
.scen-list + .scen-list { margin-top: 0; }
.scen-item { border: 1px solid var(--line); border-radius: 6px; padding: 4px 8px 5px; margin: 0 0 5px; background: var(--surface-2); cursor: pointer;
  transition: background-color var(--dur-fast), border-color var(--dur-fast), box-shadow var(--dur-fast); }
.scen-item:hover, .scen-item:focus-visible { background: var(--accent-soft); border-color: var(--accent); box-shadow: 0 2px 6px rgba(16,24,40,0.10); }
.scen-top { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.scen-name { font-weight: 600; font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.scen-input { flex: 1; min-width: 0; font-size: 12.5px; font-weight: 600; padding: 0 4px; height: 22px; border: 1px solid var(--accent); border-radius: 4px; background: var(--surface); color: var(--text); }
.scen-edit { border: 0; background: none; color: var(--muted); padding: 2px 4px; font-size: 11px; cursor: pointer; border-radius: 4px; flex: none; }
.scen-edit:hover { color: var(--accent-dark); background: var(--accent-soft); }
.scen-expanded .scen-rest { display: block; }
.scen-more { display: flex; align-items: center; gap: 6px; border: 0; background: none; color: var(--accent-dark); font-size: 12px; font-weight: 600; cursor: pointer; padding: 2px 0; }
.scen-more::after { content: attr(data-show); order: 0; }
.scen-expanded .scen-more::after { content: attr(data-hide); }
.scen-more::before { content: ""; order: 1; width: 6px; height: 6px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(45deg); margin-top: -3px; transition: transform var(--dur-fast) ease; }
.scen-more { flex-direction: row-reverse; justify-content: flex-end; }
.scen-expanded .scen-more::before { transform: rotate(-135deg); margin-top: 3px; }
.well { min-height: 130px; }

/* The Take a tour button must stay clickable under the "Hide" hover overlay */
.tour-btn { position: relative;  }

/* The whole side panel scrolls as one: settings, Run box and past runs keep their natural height */
@media (min-width: 768px) {
  .container-fluid > .row > .col-sm-3 { display: block; overflow-y: auto; overflow-x: hidden; max-height: 100%; padding-right: 10px; scrollbar-gutter: stable; }
  .container-fluid > .row > .col-sm-3 > .well { overflow: visible; min-height: 0; margin-bottom: 0; }
  .container-fluid > .row > .col-sm-3 > .sidebar-dock { flex: none; }
  .history-box { max-height: none; overflow: visible; }
}

/* The summary text unfolds from the box itself: the row grows from 0 to its full height while the text fades in, with no sliding */
.insight-body, .insight-open .insight-body { display: grid; animation: none; padding: 0; grid-template-rows: 0fr; transition: grid-template-rows var(--dur-slow) cubic-bezier(.4,0,.2,1); }
.insight-open .insight-body { grid-template-rows: 1fr; }
.insight-body-in { overflow: hidden; min-height: 0; padding: 0 14px 0 42px; opacity: 0; transition: opacity var(--dur) ease, padding-bottom var(--dur-slow) ease; }
.insight-open .insight-body-in { opacity: 1; padding-bottom: 12px; transition: opacity var(--dur-slow) ease var(--dur-fast), padding-bottom var(--dur-slow) ease; }
.insight-body-in p { margin: 0; }
.insight-body-in .insight-note { margin-top: 8px; }

.howto { padding-right: 14px; }
.tour-btn { z-index: 1; }

.tour-note { display: flex; align-items: flex-start; gap: 9px; font-size: 12.5px; line-height: 1.4; color: var(--muted); margin: -4px 0 12px; }
.tour-note .legend-dot { margin-top: 5px; }

.howto-head { display: flex; align-items: center; gap: 14px; margin-bottom: 8px; }
.howto-head .howto-title { margin: 0; }
.howto-head .tour-btn { margin: 0; }

/* Getting started stands out a little: tinted, with an accent stripe */
.howto {   border-left: 4px solid var(--accent); }
.howto-title { color: var(--accent-dark); }
.howto-num { background: var(--btn); }
.howto-close { background: var(--surface); }

.howto-open { width: max-content; }

/* Past runs: the latest run is always shown, and the earlier ones open from an arrow below it */
.history-box { padding: 10px 12px; overflow: visible; max-height: none; }
.history-title-row { font-weight: 700; font-size: 13.5px; }
.scen-rest-wrap { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--dur-slow) cubic-bezier(.4,0,.2,1); }
.scen-expanded .scen-rest-wrap { grid-template-rows: 1fr; }
.scen-rest-in { overflow: hidden; min-height: 0; opacity: 0; transition: opacity var(--dur) ease; }
.scen-expanded .scen-rest-in { opacity: 1; transition: opacity var(--dur-slow) ease var(--dur-fast); }
.scen-more { margin: 0 0 6px; }
.scen-rest { display: block !important; }

/* Compare button next to the pencil on each past run */
.scen-tools { display: inline-flex; align-items: center; gap: 2px; flex: none; }
.scen-cmp { border: 0; background: none; color: var(--muted); padding: 2px 4px; font-size: 11px; cursor: pointer; border-radius: 4px; }
.scen-cmp:hover { color: var(--accent-dark); background: var(--accent-soft); }
.diff-table td:first-child { font-weight: 600; }

/* Suggestion to link mortality a and b */

/* Dig deeper: extra views under the forecast */

/* Temperature what-if: an optional section, collapsed until wanted, styled like a plain label */
.temp-section > summary { list-style: none; display: flex; align-items: center;  cursor: pointer; font-size: 13px; font-weight: 700; padding: 2px 0; }
.temp-section > summary::-webkit-details-marker { display: none; }
.temp-section > summary::after { content: ""; margin-left: auto; width: 6px; height: 6px; border-right: 2px solid var(--muted); border-bottom: 2px solid var(--muted);
  transform: rotate(45deg); transition: transform var(--dur-fast) ease; }
.temp-section[open] > summary::after { transform: rotate(-135deg); }
.temp-optional { font-size: 11px; font-weight: 400; color: var(--muted); }
.temp-body { padding-top: 12px; }
.temp-body .form-group { margin-bottom: 12px; }
.temp-body .irs { margin-bottom: 4px; }
.temp-sens { margin-top: 4px; }
.temp-badge { font-size: 11.5px; font-weight: 700; color: #8a5a00; background: var(--warn-bg); border: 1px solid var(--warn-line); border-radius: 9px; padding: 0 8px; }
.temp-effect { font-size: 12px; color: var(--accent-dark); margin: 10px 0 8px; line-height: 1.4; }
.temp-note { font-size: 11.5px; color: var(--muted); line-height: 1.4; margin: 8px 0 10px; }

/* Suggestion to link mortality a and b */
.hint-card { display: flex; gap: 12px; background: var(--accent-soft); border: 1px solid var(--accent-line); border-left: 4px solid var(--accent); border-radius: 8px; padding: 10px 14px; margin: 4px 0 12px; }
.hint-icon { color: var(--accent); font-size: 16px; line-height: 1.5; flex: none; }
.hint-body p { margin: 0 0 8px; font-size: 13px; line-height: 1.45; max-width: 820px; }
.hint-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; }
.hint-small { font-size: 12px; color: var(--muted); }

/* Dig deeper: extra views under the forecast */
.tools { margin: 18px 0 14px; }
.tools-head { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-bottom: 8px; }
.tools-title { font-size: 17px; font-weight: 700; }
.tools-sub { font-size: 12.5px; color: var(--muted); }
.tool-tabs { display: flex; flex-wrap: wrap; gap: 8px; }
.tool-tab { display: inline-flex; align-items: center; gap: 7px; padding: 6px 14px; border: 1px solid var(--line-strong); border-radius: 18px; background: var(--surface);
  color: var(--accent-dark); font-size: 13px; font-weight: 600; cursor: pointer; transition: background-color var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast), box-shadow var(--dur-fast); }
.tool-tab:hover { background: var(--accent-soft); border-color: var(--accent); }
.tool-tab.on { background: var(--btn); border-color: var(--btn-dark); color: #fff; box-shadow: 0 1px 3px rgba(16,24,40,0.2); }
.tool-panel { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--dur-slow) cubic-bezier(.4,0,.2,1); }
.tool-panel.on { grid-template-rows: 1fr; }
.tool-panel-in { overflow: hidden; min-height: 0; }
.tool-card { margin-top: 10px; padding: 12px 16px 6px; background: var(--surface); border: 1px solid var(--line); border-radius: 8px; opacity: 0; transition: opacity var(--dur) ease; }
.tool-panel.on .tool-card { opacity: 1; transition: opacity var(--dur-slow) ease var(--dur-fast); }
.tool-card-title { font-size: 15px; font-weight: 700; margin: 0 0 6px; }
.tool-card .form-group { margin-bottom: 8px; }

/* Temperature what-if in the side panel: a plain label and control, like the settings around it */
.temp-section { margin: 4px 0 10px; }
.temp-label { font-size: 13px; font-weight: 700; margin-bottom: 0; display: flex; align-items: center; gap: 8px; }
.temp-section .form-group { margin-bottom: 2px; }
.temp-section .irs { margin-bottom: 0; }

/* Forecast readout is only as wide as its text; the jump bar under the tabs is slightly see-through */
.cert-readout { width: fit-content; max-width: 100%; }
.jump-bar { background: rgba(var(--page-rgb), 0.82); -webkit-backdrop-filter: blur(3px); backdrop-filter: blur(3px); }

/* Past runs: tags, extra buttons, clear all */
.scen-run, .scen-del, .scen-dl { border: 0; background: none; color: var(--muted); padding: 2px 4px; font-size: 11px; cursor: pointer; border-radius: 4px; }
.scen-dl:hover { color: var(--accent-dark); background: var(--accent-soft); }
.scen-run:hover { color: #1a7f37; background: var(--accent-soft); }
.scen-del:hover { color: var(--danger); background: var(--accent-soft); }
.scen-tags { display: flex; flex-wrap: wrap; gap: 5px; margin: 1px 0 2px; }
.scen-tag { font-size: 10.5px; font-weight: 700; border-radius: 9px; padding: 0 7px; }
.scen-tag.showing { background: var(--accent-soft); color: var(--accent-dark); border: 1px solid var(--accent-line); }
.scen-tag.same { background: rgba(26,127,55,0.12); color: #1a7f37; border: 1px solid rgba(26,127,55,0.35); }
html[data-theme="dark"] .scen-tag.same { color: #56d364; }
.temp-warn { color: var(--warn); }

/* Quick summary: the View hint and arrow sit right beside the title, not at the far edge */
.insight-hint { margin-left: 4px; }
.insight-chev { margin-left: 2px; }
.insight-head { justify-content: flex-start; }

.preset-table-lead { font-size: 12.5px; color: var(--muted); margin: 10px 0 4px; }
.preset-table table { font-size: 12.5px; width: 100%; }
.preset-table th, .preset-table td { padding: 5px 10px; text-align: left; vertical-align: top; }
.about-card.card-flash { animation: card-flash 2.2s ease-out; }

/* Out-of-date results: the Run button turns amber and its label changes (no glow around it) */
#run.btn.stale, #run.btn.stale:focus { background: #f2b233; border-color: #c98a0a; color: #3a2600; box-shadow: 0 1px 2px rgba(16,24,40,0.2); }
#run.btn.stale:hover { background: #e6a31f; border-color: #b57a05; color: #3a2600; box-shadow: 0 1px 2px rgba(16,24,40,0.2); }
html[data-theme="dark"] #run.btn.stale, html[data-theme="dark"] #run.btn.stale:focus { background: #f2b233; border-color: #c98a0a; color: #3a2600; }
html[data-theme="dark"] #run.btn.stale:hover { background: #e6a31f; border-color: #b57a05; color: #3a2600; }
#run { transition: background-color var(--dur-fast) ease, border-color var(--dur-fast) ease, color var(--dur-fast) ease, box-shadow .6s ease; }

/* "new" slides open between "Run" and "simulation" (and closes again) instead of the label fading */
