#temp_curve .radio { margin: 0 0 4px; }
#temp_curve .radio label { display: block; padding: 0; width: 100%; }
#temp_curve input[type=radio] { position: absolute; opacity: 0; pointer-events: none; }
#temp_curve .radio label span { display: block; padding: 5px 10px; font-size: 13px; border: 1px solid var(--line-strong); border-radius: 4px;
  background: var(--surface); color: var(--text); cursor: pointer; transition: background-color var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast); }
#temp_curve .radio label:hover span { background: var(--hover); }
#temp_curve input:checked + span { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
#temp_curve .radio label:hover input:checked + span { background: var(--btn-dark); }
