#temp_curve { margin-bottom: 10px; }

/* Temperature: the content drops out of the header as its own box */
.temp-section[open] > summary { margin-bottom: 0; }
.temp-section .temp-body { margin-top: 8px; padding: 12px 12px 6px;   border-radius: 6px;
   }
.temp-section[open] .temp-body { animation: dd-drop var(--dur) ease-out; }

/* Getting started is the page's main call to action, so it looks different from the tinted note cards
   (accent stripe on the left): a full accent outline, a fade from tint to white, and a soft shadow */
.howto { background: linear-gradient(180deg, var(--accent-soft) 0, var(--surface) 70%); border: 1.5px solid var(--accent);
  border-left-width: 1.5px; border-radius: 10px; box-shadow: 0 4px 16px rgba(43, 108, 176, .14); padding-top: 14px; }
.howto-title { font-size: 13px; font-weight: 800; letter-spacing: .08em; }
