html[data-theme="dark"] .howto { box-shadow: 0 4px 16px rgba(0, 0, 0, .35); }

/* Message laid over a past run when its settings are reloaded: the card behind fades, nothing else moves */
.history-box { position: relative; }
.scen-flash { position: absolute; z-index: 5; display: flex; align-items: center; justify-content: center; text-align: center;
  padding: 4px 10px; border-radius: 6px; font-size: 12.5px; font-weight: 600; line-height: 1.3; pointer-events: none;
  color: var(--accent-dark); background: color-mix(in srgb, var(--surface) 88%, transparent); border: 1px solid var(--accent);
  -webkit-backdrop-filter: blur(1.5px); backdrop-filter: blur(1.5px); opacity: 0; transition: opacity var(--dur-slow) ease; }
.scen-flash.on { opacity: 1; }

/* The check mark draws itself: the ring first, then the tick, with a small pop at the end */
.scen-flash { gap: 8px; }
.scen-check { flex: none; width: 22px; height: 22px; fill: none; stroke: var(--accent); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.scen-check circle { stroke-dasharray: 63; stroke-dashoffset: 63; }
.scen-check path { stroke-dasharray: 20; stroke-dashoffset: 20; }
.scen-flash.on .scen-check { animation: check-pop var(--dur) ease .55s both; }
.scen-flash.on .scen-check circle { animation: check-draw var(--dur-slow) ease-out var(--dur-fast) forwards; }
.scen-flash.on .scen-check path { animation: check-draw var(--dur) ease-out var(--dur-slow) forwards; }
@keyframes check-draw { to { stroke-dashoffset: 0; } }
@keyframes check-pop { 0% { transform: scale(1); } 50% { transform: scale(1.22); } 100% { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) {
  .scen-check circle, .scen-check path { stroke-dashoffset: 0; animation: none !important; }
  .scen-flash.on .scen-check { animation: none; }
}

/* The Temperature options sit in a tinted panel with an accent edge, so they read as a sub-section of the sidebar
   card instead of another white card inside it */
.temp-section .temp-body { background: var(--accent-soft); border: 1px solid var(--accent-line); border-left: 3px solid var(--accent); box-shadow: none; }

/* Temperature change slider: readout on top, a track that fills out from zero, a round handle, and quick-pick chips */
.temp-slider { --fc: var(--muted); --p: .5; margin-bottom: 12px; }
.temp-slider.is-cool { --fc: var(--accent); }
.temp-slider.is-warm { --fc: #D55E00; }
.temp-slider .form-group { margin-bottom: 0; }
.temp-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 2px; }
.temp-head-label { font-size: 13px; font-weight: 700; line-height: 1.2; }
.temp-value { display: inline-flex; align-items: baseline; gap: 2px; flex: none; }
.temp-input { width: 56px; padding: 1px 4px; border: 1px solid transparent; border-radius: 5px; background: transparent; text-align: right;
  font: inherit; font-size: 17px; line-height: 1.2; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--muted); }
.temp-input:hover { border-color: var(--line-strong); }
.temp-input:focus { outline: none; border-color: var(--accent); background: var(--surface); }
.temp-slider.is-cool .temp-input { color: var(--accent-dark); }
.temp-slider.is-warm .temp-input { color: #b84d00; }
html[data-theme="dark"] .temp-slider.is-warm .temp-input { color: #ff9b57; }
.temp-unit { font-size: 12px; font-weight: 600; color: var(--muted); }
.temp-delta-input { position: absolute; opacity: 0; pointer-events: none; width: 0; height: 0; }
.tslider { position: relative; height: 26px; margin: 0 9px; cursor: pointer; touch-action: none; user-select: none; -webkit-user-select: none; }
.ts-track { position: absolute; left: 0; right: 0; top: 11px; height: 4px; border-radius: 2px; background: var(--line-strong); }
.ts-fill { position: absolute; top: 0; bottom: 0; border-radius: 2px; background: var(--fc);
  left: calc(min(var(--p), .5) * 100%); width: calc((max(var(--p), .5) - min(var(--p), .5)) * 100%); }
.ts-zero { position: absolute; left: 50%; top: 7px; width: 2px; height: 12px; margin-left: -1px; border-radius: 1px; background: var(--muted); opacity: .5; }
.ts-handle { position: absolute; top: 13px; left: calc(var(--p) * 100%); width: 18px; height: 18px; margin: 0; padding: 0; border-radius: 50%;
  transform: translate(-50%, -50%); background: var(--surface); border: 1px solid var(--line-strong); box-shadow: 0 1px 3px rgba(16, 24, 40, .3);
  cursor: grab; transition: transform var(--dur-fast) ease, box-shadow var(--dur-fast) ease; }
.ts-handle:hover { transform: translate(-50%, -50%) scale(1.12); }
.tslider.dragging .ts-handle { cursor: grabbing; transform: translate(-50%, -50%) scale(1.18); box-shadow: 0 2px 8px rgba(16, 24, 40, .35); }
.ts-handle:focus { outline: none; }
.ts-handle:focus-visible { outline: 2px solid var(--muted); outline-offset: 2px; }
.ts-scale { position: relative; height: 16px; margin: 0 9px 6px; font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }
.ts-scale span { position: absolute; top: 0; transform: translateX(-50%); }
.ts-scale span:nth-child(1) { left: 0; } .ts-scale span:nth-child(2) { left: 50%; } .ts-scale span:nth-child(3) { left: 100%; }
.temp-chips { display: flex; gap: 5px; flex-wrap: wrap; }
.temp-chip { flex: 1 1 0; min-width: 0; padding: 3px 0; font-size: 11.5px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--muted);
  background: var(--surface); border: 1px solid var(--line-strong); border-radius: 12px; cursor: pointer; transition: background-color var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast); }
.temp-chip:hover { background: var(--hover); color: var(--text); }
.temp-chip.on { background: var(--btn); border-color: var(--btn-dark); color: #fff; }
.temp-badge { white-space: nowrap; flex: none; }

/* Temperature is its own optional section, not part of the preset choice below it: the arrow sits at the left of the
   title like a "show more" caret (pointing right when closed, down when open) and "optional" is in italics */
.temp-section > summary::after { display: none; }
.temp-section > summary::before { content: ""; flex: none; width: 6px; height: 6px; margin: 0 2px 0 3px;
  border-right: 2px solid var(--muted); border-bottom: 2px solid var(--muted); transform: rotate(-45deg); transition: transform var(--dur-fast) ease; }
.temp-section[open] > summary::before { transform: rotate(45deg); }
.temp-section > summary:hover::before { border-color: var(--accent); }
.temp-optional { font-style: italic; }

/* Temperature on/off switch in the section header. The checkbox only holds the state; its button sibling is the visible switch */
.temp-sw-input { position: absolute; opacity: 0; pointer-events: none; width: 0; height: 0; }
.temp-section > summary { flex-wrap: nowrap; gap: 6px; }
.temp-switch { margin-left: auto; flex: none; position: relative; width: 34px; height: 20px; padding: 0; border-radius: 10px;
  border: 1px solid var(--line-strong); background: var(--surface-3); cursor: pointer;  }
.temp-sw-knob { position: absolute; top: 1px; left: 1px; width: 16px; height: 16px; border-radius: 50%; background: var(--surface);
  box-shadow: 0 1px 3px rgba(16, 24, 40, .4); transition: transform var(--dur-fast) ease; }
.temp-switch:hover { border-color: var(--accent); }
.temp-switch:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.temp-sw-input:checked + .temp-switch { background: var(--btn); border-color: var(--btn-dark); }
.temp-sw-input:checked + .temp-switch .temp-sw-knob { transform: translateX(14px); }
/* On: the word "optional" makes way so the badge and the switch fit */
/* While it is off the options stay editable (touching them turns it on) but look inactive */
.temp-section.has-temp:has(.temp-sw-input:not(:checked)) .temp-body { opacity: .55; transition: opacity var(--dur-fast) ease; }
.temp-section.has-temp:has(.temp-sw-input:not(:checked)) .temp-body:hover { opacity: .85; }

/* The switch fades in once a temperature change is set (it keeps its space, so nothing shifts) */
.temp-switch { opacity: 0; visibility: hidden; pointer-events: none; transition: opacity var(--dur-slow) ease, visibility 0s linear var(--dur-slow), background-color var(--dur-fast) ease, border-color var(--dur-fast) ease; }
.temp-section.has-temp .temp-switch { opacity: 1; visibility: visible; pointer-events: auto; transition: opacity var(--dur-slow) ease, visibility 0s, background-color var(--dur-fast) ease, border-color var(--dur-fast) ease; }

/* A box whose height is animated when its content changes (see "Smooth resizing" in pvec.js) */
.smooth-h { display: flow-root; overflow: clip; overflow-clip-margin: 6px; }

/* "Reset range" / "Reset zoom" float over the top-right corner of the chart, so showing them moves nothing */
.reset-float { position: absolute; top: 0; right: 0; z-index: 6; }
.reset-float .btn { font-size: 12px; padding: 2px 8px; background: var(--surface); animation: fade-in var(--dur) ease-out; }
.surv-wrap { position: relative; }

/* Highlight over the bar under the mouse on the forecast and sensitivity charts (positioned by pvec.js) */
.bar-hl { position: absolute; pointer-events: none; z-index: 4; opacity: 0; background: rgba(8, 24, 48, .3); border-radius: 1px;
  transition: opacity var(--dur-fast) ease, left var(--dur-fast) ease-out, top var(--dur-fast) ease-out, width var(--dur-fast) ease-out, height var(--dur-fast) ease-out; }
.bar-hl.on { opacity: 1; }
html[data-theme="dark"] .bar-hl { background: rgba(255, 255, 255, .24); }
.tip-cell:not(:hover) .bar-hl { opacity: 0; }

/* Toast with an Undo action, fixed at the bottom of the window above the footer so nothing on the page moves */
.pv-toast { position: fixed; left: 50%; bottom: 52px; z-index: 2000; display: flex; align-items: center; gap: 14px; max-width: calc(100vw - 32px);
  padding: 10px 14px 12px; border-radius: 8px; overflow: hidden; font-size: 13px; line-height: 1.3; color: #fff; background: #1f2933;
  box-shadow: 0 6px 22px rgba(16, 24, 40, .35); opacity: 0; visibility: hidden; pointer-events: none;
  transform: translate(-50%, 12px); transition: opacity var(--dur) ease, transform var(--dur) ease, visibility 0s linear var(--dur); }
.pv-toast.on { opacity: 1; visibility: visible; pointer-events: auto; transform: translate(-50%, 0); transition: opacity var(--dur) ease, transform var(--dur) ease, visibility 0s; }
html[data-theme="dark"] .pv-toast { background: var(--surface-3); border: 1px solid var(--line-strong); }
.pv-toast-btn { border: 0; background: none; padding: 0 2px; font: inherit; font-weight: 700; color: #8dbcf0; cursor: pointer; }
.pv-toast-btn:hover, .pv-toast-btn:focus-visible { text-decoration: underline; color: #fff; outline: none; }
.pv-toast-bar { position: absolute; left: 0; bottom: 0; height: 3px; width: 100%; background: #8dbcf0; transform-origin: left; opacity: .8; }
.pv-toast.on .pv-toast-bar { animation: toast-bar linear forwards; }
@keyframes toast-bar { from { transform: scaleX(1); } to { transform: scaleX(0); } }
@media print { .pv-toast { display: none !important; } }

/* The badge ("+2.5 °C") and the word "optional" swap places smoothly: one slides and fades out while the other opens and fades in.
   The badge is filled in by pvec.js the moment the value or the switch changes, so there is no wait for the server. */
.temp-optional { display: inline-block; overflow: hidden; white-space: nowrap; max-width: 60px; opacity: 1;
  transition: max-width var(--dur) ease, opacity var(--dur-fast) ease, margin var(--dur) ease; }
.temp-badge-wrap { display: inline-flex; flex: none; overflow: hidden; max-width: 0; opacity: 0; margin-left: -6px;
  transition: max-width var(--dur) ease, opacity var(--dur) ease, margin var(--dur) ease; }
.temp-section.badge-on .temp-optional { max-width: 0; opacity: 0; margin-left: -6px; }
.temp-section.badge-on .temp-badge-wrap { max-width: 90px; opacity: 1; margin-left: 0; transition-delay: 0s, .05s, 0s; }

/* Past runs: "Download all" sits to the left of "Clear all" */

/* Past runs: "Download all" and "Clear all" are icons at the end of the line, each with a tooltip that opens above it */
.history-sub { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.hist-actions { display: inline-flex; gap: 2px; flex: none; }
.hist-icon { position: relative; width: 24px; height: 22px; padding: 0; border: 0; border-radius: 4px; background: none; color: var(--muted);
  font-size: 12px; cursor: pointer; transition: background-color var(--dur-fast), color var(--dur-fast); }
.hist-icon:hover, .hist-icon:focus-visible { background: var(--accent-soft); color: var(--accent-dark); outline: none; }
