  padding: 6px 9px; border-radius: 4px; text-align: left; white-space: normal; font-size: 12px; line-height: 1.35; font-weight: 400; color: #fff;
  background: rgba(33, 37, 41, 0.94); pointer-events: none; opacity: 0; visibility: hidden;
  transition: opacity var(--dur-fast) ease, visibility 0s linear var(--dur-fast); }
.hist-icon[data-tip]:hover::after, .hist-icon[data-tip]:focus-visible::after { opacity: 1; visibility: visible;
  transition: opacity var(--dur-fast) ease var(--dur), visibility 0s linear var(--dur); }

/* Past runs: the two icons sit in the top right corner of the box, level with the title, and are a little larger */
.history-title-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.hist-icon { width: 30px; height: 28px; font-size: 15px; border-radius: 6px; }
.hist-actions { margin: -3px -4px -3px 0; }
.hist-icon[data-tip]::after { right: -2px; }

/* Past runs header: the title and the instruction line on the left, the two icons centred against both lines on the right */
.history-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
.history-header .history-title-row { display: block; }
.history-header .history-sub { display: block; margin: 1px 0 0; }
.history-header .hist-actions { margin: 0 -4px 0 0; align-self: center; }

/* Brand purple (the logo's colour), kept to small touches: a hairline across the top of the page, the tab dots for unseen results,
   and the "Showing" tag on Past runs. Blue stays for controls and data. */
body::before { content: ""; position: fixed; top: 0; left: 0; right: 0; height: 3px; z-index: 3000; pointer-events: none;
  background: linear-gradient(90deg, var(--brand), var(--accent)); }
@media print { body::before { display: none; } }
.scen-tag.showing { background: var(--brand-soft); color: var(--brand); border-color: var(--brand-line); }

/* Toasts: wrap long messages, a close button, and a coloured edge for warnings and errors */
.pv-toast { max-width: min(520px, calc(100vw - 32px)); }
.pv-toast-text { white-space: normal; }
.pv-toast.err { border-left: 4px solid #e5604f; padding-left: 12px; }
.pv-toast.warn { border-left: 4px solid #f2b233; padding-left: 12px; }
.pv-toast-x { border: 0; background: none; padding: 0 2px; margin-left: -4px; font-size: 18px; line-height: 1; color: rgba(255,255,255,.65); cursor: pointer; }
.pv-toast-x:hover, .pv-toast-x:focus-visible { color: #fff; outline: none; }

/* The Run button and Past runs are one panel, stuck to the bottom of the sidebar so both stay in view while the settings scroll behind
   them. A shadow above the panel appears only while something is actually sliding underneath it (the "stuck" class, set in pvec.js). */
.sidebar-dock { z-index: 5; margin-top: 10px; background: var(--surface); border: 1px solid var(--line);
  border-radius: 4px; box-shadow: 0 1px 2px rgba(16, 24, 40, .04); transition: box-shadow var(--dur) ease; }
@media (min-width: 768px) { .sidebar-dock { position: sticky; bottom: 0; } }   /* on a phone the panel scrolls with the page instead of covering it */
.sidebar-dock.stuck { box-shadow: 0 -10px 14px -10px rgba(16, 24, 40, .3), 0 1px 2px rgba(16, 24, 40, .04); }
.sidebar-dock > .run-dock { position: static; margin: 0; border: 0; border-radius: 0; box-shadow: none; background: none; }
.sidebar-dock > .history-box { margin: 0; border: 0; border-top: 1px solid var(--line); border-radius: 0; box-shadow: none; background: none; }
/* A long list of runs scrolls inside the panel, so the panel never takes over the sidebar */
.sidebar-dock #scenario_list { max-height: clamp(90px, 22vh, 220px); overflow-y: auto; overflow-x: hidden; }

/* "Fix before running" list under the Run button, and the held-off button */
.run-issues { font-size: 12px; line-height: 1.35; color: var(--danger-text); }
.run-issues:not(:empty) { margin-top: 8px; padding: 7px 9px; border: 1px solid var(--danger); border-radius: 6px; background: var(--danger-bg); }
.run-issues .ri-head { font-weight: 700; margin-bottom: 2px; }
.run-issues ul { margin: 0; padding-left: 16px; }
.run-issues a { color: inherit; font-weight: 600; text-decoration: underline; }
.run-issues .ri-more { list-style: none; margin-left: -16px; color: var(--muted); }
#run.blocked, #run.blocked:hover { opacity: .5; cursor: not-allowed; }
.assump-card.focus-flash { animation: card-focus 1.6s ease-out; }
@keyframes card-focus { 0% { box-shadow: 0 0 0 3px var(--danger); } 100% { box-shadow: 0 0 0 3px transparent; } }

/* Chart cursors, and the one-time tip on charts that can be dragged */
#forecast_plot, .surv-cell .shiny-plot-output { cursor: crosshair; }
#sens_plot { cursor: pointer; }
.chart-hint { display: flex; align-items: center; gap: 8px; margin: 2px 0 8px; padding: 5px 8px; border-radius: 6px; font-size: 12px; color: var(--muted);
  background: var(--surface-2); border: 1px dashed var(--line-strong); max-height: 40px; overflow: hidden;
  transition: opacity var(--dur) ease, max-height var(--dur) ease, margin var(--dur) ease, padding var(--dur) ease, border-width var(--dur) ease; }
.chart-hint .fa, .chart-hint svg { color: var(--accent); flex: none; }
.chart-hint span { flex: 1 1 auto; }
.chart-hint-x { flex: none; border: 0; background: none; padding: 0 4px; font-size: 16px; line-height: 1; color: var(--muted); cursor: pointer; }
.chart-hint-x:hover { color: var(--text); }
.chart-hint.gone { opacity: 0; max-height: 0; margin: 0; padding-top: 0; padding-bottom: 0; border-width: 0; }

